import type { Term } from './data'

const reviewed = 'November 2026'

const t = (
  term: string,
  slug: string,
  aliases: string[],
  plainMeaning: string,
  summary: string,
  interpretations: string[],
  example: string,
  contextClues: string,
  opener: string,
  category: Term['category'],
  concern: Term['concern'],
): Term => ({
  term, slug, aliases, plainMeaning, summary, interpretations, example, contextClues, opener, category, concern, reviewed,
})

export const currentTerms3: Term[] = [
  t('algorithm', 'algorithm', ['the algo', 'algos', 'for you algorithm'], 'The system that decides what a feed shows next.', 'Teens talk about “the algo” as if it were a moody person: it pushes some videos and buries others. It learns from what they watch, not just what they search.', ['Complaining that their feed is stuck on one topic.', 'Trying to “train” recommendations.', 'A theory about why a post flopped.'], '“The algo thinks I want only gym videos.”', 'Useful media literacy. What they watch teaches the feed. You can ask what it’s been feeding them without taking the phone.', '“What’s the algorithm convinced you like this month?”', 'Social Media Culture', 'harmless'),
  t('duet', 'duet', ['duet this', 'tiktok duet', 'duetted'], 'A video placed side by side with someone else’s video.', 'A TikTok format. People react, harmonize, stitch a joke, or argue with the original creator in public.', ['A fun reaction or collaboration.', 'Public disagreement.', 'Piling on a stranger’s video.'], '“She duetted the tutorial and fixed the ending.”', 'Creative uses are ordinary. A duet made to mock a classmate is a call-out with an audience.', '“Was the duet with a friend, or about someone who didn’t ask?”', 'Social Media Culture', 'discuss'),
  t('stitch', 'stitch', ['stitched', 'stitch this', 'tiktok stitch'], 'Clipping someone else’s video and adding your own response in front of or after it.', 'Like a duet, but sequential. Huge for commentary, jokes, and arguments.', ['Comedy or added context.', 'A critique of a take.', 'A way to drag someone with their own clip.'], '“He stitched the rumor and asked for receipts.”', 'Commentary can be fair or a pile-on. The original person may not have agreed to the audience.', '“Did the stitch add context, or just invite people to jump in?”', 'Social Media Culture', 'discuss'),
  t('storytime', 'storytime', ['story time', 'storytime tiktok', 'gather round'], 'A video or post that tells a personal story, often dramatic.', 'A format: “storytime about the worst group project.” Some are funny. Some share other people’s private business.', ['A funny personal story.', 'Gossip about a real classmate.', 'A dramatized story that only half happened.'], '“Storytime: I waved at a stranger.”', 'Ask whether the people in the story know it’s being told. Names and schools make gossip sharper.', '“Was that story yours to tell?”', 'Social Media Culture', 'discuss'),
  t('day in the life', 'day-in-the-life', ['ditl', 'day in my life', 'daily vlog'], 'A video following someone’s routine.', 'School, practice, skincare, “get ready,” commute. Often aspirational. Sometimes a highlight reel that makes ordinary days feel behind.', ['Sharing a routine.', 'Performing a polished life.', 'A calming or motivating watch.'], '“I watched three day-in-the-life videos instead of starting mine.”', 'Harmless format. Comparison is the side effect worth naming.', '“Do those routines look like real days or like ads?”', 'Social Media Culture', 'harmless'),
  t('haul', 'haul', ['clothing haul', 'shein haul', 'mini haul'], 'Showing a pile of things you bought.', 'Common with clothes and Amazon boxes. Can be fun, and can normalize a lot of spending and returns.', ['A fun show-and-tell.', 'Pressure to buy the same items.', 'Hidden spending.'], '“Haul video later, don’t judge the bags.”', 'Ask about money and returns without banning taste. Fast-fashion hauls also raise a waste conversation if you want one.', '“What in the haul was a want, and what was a ‘the video made me’?”', 'Social Media Culture', 'discuss'),
  t('pr package', 'pr-package', ['pr package', 'gifted pr', 'seeded'], 'Free products a brand sends a creator, hoping for a post.', 'PR means public relations, not Puerto Rico, in this sentence. “Gifted” on a post should mean they didn’t pay. It is still advertising.', ['A creator got free stuff.', 'Your child hopes brands will send them things.', 'A post that is an ad but doesn’t say so.'], '“She only posts PR now.”', 'Teach the label. Free doesn’t mean honest, and small creators get pitched too.', '“If something says gifted, do you read it as a review or an ad?”', 'Social Media Culture', 'discuss'),
  t('link in bio', 'link-in-bio', ['lib', 'check my bio', 'the link'], 'A URL the creator parked on their profile because the post itself can’t hold a clickable link.', 'Often a store, a song, or a signup. Also a classic place scammers hide “free” prizes.', ['A normal shop or playlist.', 'A petition or fundraiser.', 'A scam or a suspicious download.'], '“Link in bio for the notes.”', 'Known creators’ shops are one thing. “You won, link in bio” is another.', '“Do you tap those, and how do you tell a real one?”', 'Social Media Culture', 'discuss'),
  t('instagram notes', 'instagram-notes', ['ig notes', 'notes sticker', 'profile note'], 'A short status, about 60 characters, that sits above someone’s profile or DMs.', 'Song lyrics, inside jokes, cryptic feelings, or “hi.” Friends treat it like a tiny billboard. Not the same as the iPhone Notes app apology.', ['A mood or a lyric.', 'A public flirt or subtweet.', 'A way to say something without posting a story.'], '“Their note is just a lyric and now the chat is spiraling.”', 'Cryptic notes invite overreading. You can ask who it’s for without treating a lyric as a crisis.', '“Are notes inside jokes, or a way to say something you don’t want to post?”', 'Social Media Culture', 'harmless'),
  t('broadcast channel', 'broadcast-channel', ['ig channel', 'broadcast', 'the channel'], 'A one-to-many chat. The owner posts; followers react with emoji more than they talk.', 'Instagram, WhatsApp, and similar apps use these for updates. Creators and classmates both run them. Less private than it feels, because screenshots exist.', ['A club, team, or creator update.', 'A classmate’s rumor channel.', 'A place that feels inner-circle but is actually large.'], '“She announced the party on her broadcast.”', 'Ask who else is in it. “Private” channels with a hundred people are not private.', '“Who can see that channel?”', 'Social Media Culture', 'discuss'),
  t('restrict', 'restrict', ['restricted', 'ig restrict', 'restrict mode'], 'A quiet Instagram limit. A restricted person can still comment, but others don’t see those comments unless you approve them.', 'Softer than a block. People use it to mute drama without announcing a war. The restricted person often doesn’t know.', ['Creating distance after weird comments.', 'Avoiding a fight.', 'Keeping an eye on someone while pretending nothing changed.'], '“I didn’t block him, I restricted him.”', 'A reasonable tool. If they’re restricted by someone they care about, the confusion hurts. You can explain the feature plainly.', '“Did restricting feel like a boundary or like a secret fight?”', 'Social Media Culture', 'discuss'),
  t('vanish mode', 'vanish-mode', ['ig vanish', 'vanishing chats', 'vanish mode on'], 'A chat mode where messages disappear after they’re seen.', 'Instagram and similar apps offer it. People use it for jokes and for conversations they don’t want saved. Disappearing is not the same as private: screenshots and screen recordings still happen.', ['Low-stakes jokes.', 'Flirting or secrets.', 'Pressure to move a conversation somewhere it won’t be saved.'], '“Turn vanish mode on first.”', 'If someone insists on disappearing messages before they ask for photos or a meetup, that’s a cue to slow down.', '“What kinds of chats use vanish mode in your group?”', 'Sensitive Safety Topics', 'discuss'),
  t('view once', 'view-once', ['view once photo', 'one time view', 'opens once'], 'A photo or video that is meant to be seen a single time and then disappear.', 'Common on Snapchat and WhatsApp-style chats. Used for silly faces and for images people don’t want saved. Recipients can still screenshot or photograph the screen.', ['A goofy picture.', 'A photo they were nervous to send.', 'Pressure to send something intimate “because it disappears.” It may not.'], '“Send it view once if you’re embarrassed.”', 'Teach the limit of the feature. Anything sent can be copied. Intimate images of minors are a safety issue even if a button said once.', '“Do you know view once can still be saved by the other person?”', 'Sensitive Safety Topics', 'attention'),
  t('snap map', 'snap-map', ['snapmap', 'the map', 'snap location'], 'A Snapchat map that can show friends where you are.', 'Helpful for finding a group at a game. Risky if it’s public, if a huge friend list can see it, or if a location is home or school on a schedule.', ['Finding friends at an event.', 'Forgetting the map is on.', 'Someone they barely know watching their routine.'], '“Check Snap Map, we’re by the buses.”', 'Ghost mode exists. Home, school, and a wide friend list are worth a settings check together, not a raid of the phone.', '“Who can see you on the map right now?”', 'Sensitive Safety Topics', 'attention'),
  t('ghost mode', 'ghost-mode', ['snap ghost mode', 'ghostmode'], 'A Snap Map setting that hides your live location.', 'The private option. “I’m on ghost mode” means they don’t want to be seen on the map. It is not the same as ghosting a person.', ['Choosing privacy.', 'Hiding from a specific person after drama.', 'Explaining why they “disappeared” from the map.'], '“I’m on ghost mode, stop asking where I am.”', 'A healthy default for a lot of kids. If they’re hiding because someone is monitoring them in a scary way, ask about that person.', '“Ghost mode from everyone, or from someone specific?”', 'Social Media Culture', 'harmless'),
  t('bereal', 'bereal', ['be real app', 'time to bereal', 'bereal streak'], 'An app that prompts once a day for a spontaneous photo from both cameras.', 'The point is unpolished life. Teens still angle it, retake it, or post something funny. There is a time window and social pressure not to miss it.', ['A daily photo with friends.', 'Pressure to show where they are.', 'A streak they don’t want to break.'], '“Bereal went off in the middle of class.”', 'Usually mild. Location and who can see the post are the settings questions.', '“Do you like the Bereal, or is it one more streak to keep?”', 'Social Media Culture', 'discuss'),
  t('locket', 'locket', ['locket widget', 'locket app', 'locket pics'], 'An app that puts a friend’s live photo on your home-screen widget.', 'Closer than a story: a small circle sees pictures throughout the day. Sweet, and easy to feel watched by.', ['A best-friend widget.', 'A crush thing.', 'Pressure to send photos all day, including ones they wouldn’t post publicly.'], '“She sent a Locket of the notes she stole.”', 'Ask who’s on the widget. A small trusted circle is the design. A large one is a feed again.', '“Who’s on your Locket, and do photos stay in that group?”', 'Social Media Culture', 'discuss'),
  t('snap score', 'snap-score', ['snapscore', 'high snap score', 'snapchat score'], 'A Snapchat number that rises as you send and receive snaps.', 'Not a measure of worth, but teens compare it. A high score means a lot of snapping, not a lot of close friends. It can be gamed.', ['A meaningless flex.', 'A sign someone snaps constantly.', 'Jealousy or status talk.'], '“His score is insane and he still has no one to sit with.”', 'A nice opening about what the number doesn’t measure.', '“What do you think a high snap score actually proves?”', 'Social Media Culture', 'harmless'),
  t('flop', 'flop', ['flopped', 'flop era', 'that flopped'], 'A post, song, or moment that failed to get the reaction someone wanted.', 'The opposite of going viral. Also a joke about their own life: “my flop era.”', ['A video got no views.', 'Self-mockery.', 'A fandom insulting an artist’s release.'], '“I posted the edit and it flopped.”', 'Harmless unless their mood rides entirely on numbers.', '“What would a non-flop day look like offline?”', 'Social Media Culture', 'harmless'),
  t('viral', 'viral', ['going viral', 'it went viral', 'viral video'], 'Spreading fast to a huge audience, often beyond the people it was meant for.', 'Sometimes a dream, sometimes a nightmare if the video is a fight, a mistake, or a classmate who didn’t consent.', ['A fun clip blew up.', 'A joke they hope spreads.', 'A real person being exposed to strangers.'], '“Don’t post it, I don’t want it going viral.”', 'Believe “I don’t want this online.” Virality removes control.', '“If something about you started spreading, what would you want me to do?”', 'Social Media Culture', 'discuss'),
  t('reply guy', 'reply-guy', ['reply guys', 'that reply guy', 'reply guy energy'], 'Someone, often a man or boy, who constantly replies to posts fishing for attention.', 'An insult for needy, condescending, or thirsty replies. Sometimes fair, sometimes used to dismiss any disagreement.', ['Naming an annoying commenter.', 'Teasing a friend who replies too fast.', 'Shutting down a real point by attacking the person.'], '“Ignore him, he’s a reply guy.”', 'The behavior—condescension, thirst, pile-ons—is worth naming. The label can also become lazy.', '“What makes someone a reply guy instead of just a person who disagreed?”', 'Social Media Culture', 'discuss'),
  t('notes app apology', 'notes-app-apology', ['notes app', 'apology notes', 'screenshot apology'], 'A public apology written in a phone notes app, screenshotted, and posted.', 'A whole genre. Some are sincere. A lot are PR, vague, or posted because an audience demanded one. Teens parody them.', ['A real attempt to own harm.', 'A performance with no change behind it.', 'A meme format.'], '“The apology was a notes app screenshot and nobody bought it.”', 'You can talk about what a real apology includes: who was hurt, what will change, and not centering yourself.', '“What would make an apology feel real to you?”', 'Social Media Culture', 'discuss'),
  t('snark page', 'snark-page', ['snark', 'snark sub', 'snark account'], 'An account or forum dedicated to mocking a creator, classmate, or community.', '“Snark” pretends to be witty criticism. A lot of it is sustained bullying, body commentary, and rumor. School snark pages are a known harm.', ['Media criticism that stays about the work.', 'A hate-following hobby.', 'A page about real kids at a real school.'], '“There’s a snark page about our grade.”', 'If classmates are the target, treat it as bullying infrastructure. Screenshots, reports, and support for the target matter more than the joke.', '“Is the snark about a celebrity, or about people you know?”', 'Sensitive Safety Topics', 'attention'),
  t('confession page', 'confession-page', ['school confessions', 'confessions account', 'confess page'], 'An anonymous account that posts submissions about people at a school or in a community.', 'Crushes, secrets, and cruelty arrive in the same feed. Anonymity makes rumors cheap.', ['Harmless crush posts.', 'Rumors about someone’s body, sexuality, or family.', 'A page adults at school don’t know about yet.'], '“Don’t submit that to the confession page.”', 'Anonymous does not mean harmless, and it does not mean untraceable. Targets deserve backup.', '“What happens to someone who gets posted there?”', 'Sensitive Safety Topics', 'attention'),
  t('ngl app', 'ngl-app', ['ngl.link', 'ask me anything ngl', 'anonymous questions'], 'An app or link that lets people send anonymous questions to a user’s story.', 'Different from the abbreviation ngl (“not gonna lie”). The NGL app and lookalikes are famous for anonymous messages, including insults, and for nudging users to share the link.', ['Silly questions from friends.', 'A wave of anonymous insults.', 'A prompt that feels like bullying but is hard to source.'], '“I put my NGL link up and immediately regretted it.”', 'You can talk about turning it off. Anonymous cruelty is still cruelty. Don’t confuse this with someone saying “ngl.”', '“Were the anonymous messages from friends being dumb, or did they get mean?”', 'Sensitive Safety Topics', 'discuss'),
  t('tellonym', 'tellonym', ['sendit', 'anonymous ask', 'yellow app'], 'Another anonymous-question app. Sendit is a sibling in the same genre.', 'People post the link, receive unnamed messages, and screenshot the funny or awful ones. The design rewards attention, including mean attention.', ['Jokes between friends.', 'Crushes.', 'Harassment with no name attached.'], '“Tellonym said I should kill my playlist. Rude but fair.”', 'If messages attack their body, identity, or safety, save evidence and consider reporting. They don’t owe the internet an open inbox.', '“Do you know who’s actually sending those?”', 'Sensitive Safety Topics', 'discuss'),
  t('parasocial', 'parasocial', ['parasocial relationship', 'parasocialing', 'one sided fandom'], 'A one-sided bond with a creator, celebrity, or fictional character who does not know you.', 'Extremely common and not automatically unhealthy. It becomes heavy when a stranger’s silence feels like rejection, or when spending and secrecy orbit one creator.', ['A normal fandom attachment.', 'A comfort during a lonely stretch.', 'Distress, spending, or taking a creator’s boundaries as a personal betrayal.'], '“The streamer didn’t read my message and I took it personally. That’s parasocial, I know.”', 'You can respect the comfort and still ask what happens when the creator disappoints them.', '“What do you get from that creator that you’re not getting offline?”', 'Social Media Culture', 'discuss'),
  t('sasaeng', 'sasaeng', ['sasaeng fan', 'stalker fan'], 'An obsessive fan who crosses into stalking: private schedules, addresses, illegal photos, or harassment of an idol.', 'A K-pop term teens know even if they don’t follow K-pop closely. It is not a cute word for a big fan. It describes harm.', ['A news story about a celebrity.', 'A joke that minimizes stalking.', 'Behavior aimed at a local creator or classmate. Take that seriously.'], '“That’s not a fan account, that’s sasaeng behavior.”', 'If the target is someone they know, drop the fandom vocab and talk about stalking, photos, and safety.', '“Where’s the line between a big fan and someone who’s scaring the person?”', 'Sensitive Safety Topics', 'attention'),
  t('solo stan', 'solo-stan', ['akgae', 'solo stan behavior', 'only stans one'], 'A fan who supports one member of a group and ignores or attacks the rest.', 'Common in K-pop and boy-band spaces. Akgae is the harsher word for a solo fan who harasses other members. Most solo preferences are harmless.', ['Having a favorite.', 'Trash-talking the rest of the group.', 'Harassing artists or other fans.'], '“I solo stan her but I don’t hate the group.”', 'A favorite is fine. Harassment campaigns are not a hobby to shrug at.', '“Do people in that fandom go after the members they don’t like?”', 'Social Media Culture', 'discuss'),
  t('fanfic', 'fanfic', ['fanfiction', 'fic', 'ao3 fic'], 'Fiction written by fans using existing characters or real people.', 'A huge teen reading and writing world. Ranges from sweet adventure to explicit sexual content. The rating and tags are the map.', ['A creative hobby.', 'Romance stories about characters.', 'Explicit or dark content. Tags exist for a reason.'], '“I’m three chapters into a fic and I have homework.”', 'Writing is a skill. You can ask about ratings the way you’d ask about a movie. Shame makes them hide the explicit stuff instead of learning limits.', '“Do the stories you read have ratings, and do you check them first?”', 'Social Media Culture', 'discuss'),
  t('ao3', 'ao3', ['archive of our own', 'on ao3'], 'Archive of Our Own, a major fanfiction site with detailed warning tags.', 'Teens use it because it will host stories other platforms delete. Tags can warn about violence, sex, and darker themes. They only help if someone reads them.', ['Looking up a story about a show they love.', 'Reading explicit fiction.', 'Posting their own writing.'], '“It’s on ao3, so check the tags.”', 'Tags are a parental ally. Learn a few: graphic violence, underage, rape/non-con. “Underage” on a sexual story is a hard line to talk about plainly.', '“Show me how the tags work before you open a story.”', 'Social Media Culture', 'discuss'),
  t('wattpad', 'wattpad', ['wattpad story', 'wattpad book'], 'A story site popular for teen romance, fanfiction, and original novels.', 'Quality varies wildly. Some stories are sweet. Some are explicit, poorly moderated, or written about real classmates.', ['Reading or writing stories.', 'A crush story about a celebrity.', 'A story about a real person at school. That’s a consent problem.'], '“Everyone’s reading the same Wattpad and pretending they’re not.”', 'Ask whether real people are characters. That’s the bright line.', '“Are the characters fictional, or based on people you know?”', 'Social Media Culture', 'discuss'),
  t('booktok', 'booktok', ['book tok', 'booktok recommendation'], 'TikTok’s book community: recommendations, tropes, and sometimes explicit romance marketed with cute labels.', 'A real reading culture. Also a pipeline to sexual content described as “spicy” rather than adult. Dark romance is a major subcategory.', ['Genuine reading enthusiasm.', 'Recommendations that skip age and content warnings.', 'Pressure to read whatever is trending.'], '“BookTok said this one destroyed them.”', 'Ask what “spicy” and “dark” mean in the recommendation before you ban reading. You want them to be able to tell you when a book was too much.', '“What do the comments mean by spicy or dark in that one?”', 'Social Media Culture', 'discuss'),
  t('dark romance', 'dark-romance', ['dark rom', 'morally gray', 'bully romance'], 'Romance stories built around control, cruelty, crime, or dubious consent, often sold as fantasy.', 'Very popular with teen readers. The fantasy is not a how-to, and it is also not automatically harmless. Stalking, coercion, and “he hurts me but it’s hot” plots are common.', ['A fictional trope they can separate from real dating.', 'Confusion about what romance is supposed to feel like.', 'A book that scared or grossed them out and they don’t have language for it.'], '“It’s dark romance, so the guy is awful on purpose.”', 'You can say fiction can be intense and still ask what they think is okay in a real relationship. Don’t mock the genre if you want the truth.', '“What parts are fantasy, and what would be a red flag if a real person did them?”', 'Relationships & Dating', 'discuss'),
  t('coquette', 'coquette', ['coquette aesthetic', 'bow aesthetic', 'lana core'], 'A hyper-feminine look: bows, pink, lace, soft romance.', 'A fashion aesthetic. Some adults panic because the word sounds sexual. The clothes are often just a cute style. Separate the outfit from adult sexualization of minors.', ['A clothing and makeup style.', 'A music and photo mood.', 'Adults sexualizing a minor’s cute photos. That reaction is the problem, not the bows.'], '“The bow is coquette, not that deep.”', 'You can like the style and still talk about comments from strangers on photos.', '“Who comments on those pictures, and do any of them feel off?”', 'Social Media Culture', 'discuss'),
  t('clean girl', 'clean-girl', ['clean girl aesthetic', 'slick bun', 'that clean look'], 'A polished “natural” look: slick hair, gold hoops, minimal makeup, matching loungewear.', 'A trend that pretends to be effortless and often takes products, money, and a specific kind of face and hair. Teens feel it as a standard.', ['A makeup routine they enjoy.', 'Comparison and “why don’t I look like that.”', 'Just a hairstyle for practice or a game.'], '“I tried the clean-girl bun and it lasted six minutes.”', 'The routine can be fun. The standard can be narrowing. Worth saying out loud.', '“How much of that look is a joke, and how much feels required?”', 'Social Media Culture', 'discuss'),
  t('that girl', 'that-girl', ['that girl routine', 'becoming that girl'], 'The idealized productive girl: early morning, green juice, perfect grades, perfect skin.', 'A  motivational trend that slides into self-surveillance. Some teens use it as a reset. Some use it to punish themselves for normal rest.', ['A short-lived routine experiment.', 'Helpful structure.', 'A standard that makes ordinary days feel like failure.'], '“I’m trying the that-girl morning and I already hate it.”', 'Ask what they think is wrong with the days that don’t look like the video.', '“Which part of the routine actually helps, and which part is punishment?”', 'Mental Well-being', 'discuss'),
  t('office siren', 'office-siren', ['office siren aesthetic', 'siren office'], 'A 2024 fashion trend: office clothes styled in a deliberately sultry way.', 'Glasses, pencil skirts, slick hair. Mostly dress-up for people who do not have an office. The “siren” part is sexual on purpose, often as costume.', ['Playing with a costume.', 'Older-teen fashion.', 'Comments from adults on a minor’s photos. That’s the issue to watch.'], '“The blazer is office siren, the backpack ruins it.”', 'Costume talk can stay light. Strangers sexualizing school photos should be blocked and, if persistent, reported.', '“Are the comments on that look from friends your age?”', 'Social Media Culture', 'discuss'),
  t('mob wife', 'mob-wife', ['mob wife aesthetic', 'fur coat era'], 'A 2024 trend of big fur, gold, leopard print, and loud glamour, joking about mafia-movie wives.', 'Fashion, not organized crime. The joke is excess and confidence.', ['A costume or outfit joke.', 'A makeup look.', 'Movie references.'], '“Leopard print is my mob wife moment.”', 'If actual crime, weapons, or “my uncle’s business” enters the chat, that’s no longer the aesthetic.', '“Show me the outfit. Is the mob part a joke?”', 'Social Media Culture', 'harmless'),
  t('girl dinner', 'girl-dinner', ['girl dinner trend', 'snack dinner'], 'A snacky, random meal instead of a “real” dinner, joked about as a girl thing.', 'Sometimes a funny plate of pickles and cheese. Sometimes a cover for not eating enough. The joke spread in 2023 and stuck.', ['A silly snack plate.', 'Autonomy: they didn’t want a full meal.', 'A pattern of skipping meals dressed up as a trend.'], '“Girl dinner was olives and a Coke.”', 'One silly plate is not an eating disorder. Repeated “I only did girl dinner” plus body worry is a check-in, without diet talk.', '“Is girl dinner a joke night, or are real meals getting rare?”', 'Mental Well-being', 'discuss'),
  t('girl math', 'girl-math', ['girl math trend', 'the math maths'], 'Joke logic that makes spending feel free. “It was on sale, so I made money.”', 'A comedy format. It can also train sloppy money thinking if every purchase gets a punchline.', ['A joke they understand as a joke.', 'Justifying a purchase to friends or to you.', 'Gendered teasing. The joke often makes girls the punchline.'], '“Girl math says returning it means I profited.”', 'You can laugh and still ask what the thing cost. Skip the lecture that girls can’t do math. That’s not what you mean, and they’ll hear it.', '“Walk me through the girl math, then the receipt.”', 'Social Media Culture', 'harmless'),
  t('I’m just a girl', 'im-just-a-girl', ['just a girl', 'i’m just a girl moment'], 'A joke that leans on a helpless, feminine stereotype. Sometimes irony, sometimes an excuse.', 'Spread as a sound and a caption for spilling, bad driving, or not wanting to do a task. It can be playful self-roast or a way to duck responsibility.', ['Irony about a stereotype.', 'A bid to get out of a task.', 'A joke that shrinks girls if it hardens into a belief.'], '“I can’t open the jar, I’m just a girl.”', 'Humor is fine. If they use it to avoid skills they want, you can name that without killing the joke.', '“Is that a bit, or do you actually want me to take it over?”', 'Social Media Culture', 'harmless'),
  t('hot girl walk', 'hot-girl-walk', ['hot girl walking', 'walk but make it hot'], 'A walk taken as a confidence ritual: phone stays mostly away, posture up, thoughts on goals.', 'A 2020s wellness trend. Usually a good walk with branding. Sometimes tangled up in appearance pressure.', ['Actual exercise and a mood boost.', 'A joke about walking to the mailbox.', 'A body-focused rule set that stops being fun.'], '“I did a hot girl walk and came back less annoyed.”', 'Encourage the walk. Notice if the rules are about looking hot for an audience rather than feeling okay.', '“What do you think about on the walk?”', 'Mental Well-being', 'harmless'),
  t('everything shower', 'everything-shower', ['the everything shower', 'shower routine'], 'A long shower routine: hair, shave, mask, body care, the full reset.', 'Self-care content. Can be genuinely soothing or a two-hour production that wrecks a bedtime.', ['A reset they enjoy.', 'A content routine copied from videos.', 'Avoidance: the routine expands to fill the evening.'], '“I need an everything shower and then I’ll start homework.”', 'The hygiene is not the concern. The clock is. You can negotiate length without mocking the products.', '“How long does the full version actually take?”', 'Mental Well-being', 'harmless'),
  t('bold glamour', 'bold-glamour', ['bold glamour filter', 'tiktok bold glamour', 'aging filter'], 'A face filter that adds heavy, realistic-looking makeup or changes apparent age.', 'These filters are smoother than cartoon ones, so people forget they’re on. They change beauty standards and can mess with how teens see their own face.', ['A one-time funny filter.', 'Posting only with the filter.', 'Distress at their real face after using it.'], '“I look wrong without the filter now.”', 'That last sentence is the conversation. No need to ban every filter. Do talk about the before-and-after feeling.', '“When you turn it off, what do you think the camera stole?”', 'Social Media Culture', 'discuss'),
  t('fox eye', 'fox-eye', ['fox eye trend', 'fox eye lift'], 'A makeup or surgery-style look that lifts the outer eyes. It has been criticized for copying and mocking Asian eye shapes.', 'Teens may copy a tutorial without the history. The conversation is about where the look comes from and who gets mocked for the same features.', ['A makeup tutorial.', 'A joke or insult about someone’s eyes.', 'Pressure toward cosmetic procedures.'], '“The tutorial is a fox-eye lift with tape.”', 'Tape and makeup are reversible. Slurs and “jokes” about eyes are not a trend to join. Surgery talk in minors needs a slow, adult conversation.', '“Do you know why some people find that trend insulting?”', 'Social Media Culture', 'discuss'),
  t('traumacore', 'traumacore', ['trauma core', 'traumacore edit'], 'An aesthetic that uses childhood imagery, medical motifs, or sad music to depict trauma, sometimes artfully and sometimes as a vibe.', 'It can be expression and it can be romanticizing pain. Kids who are actually struggling may live in these tags.', ['Art about hard feelings.', 'A style they like without a personal story.', 'Content that makes self-harm or abuse look beautiful. That’s a check-in.'], '“The edit was traumacore and it made me sad on purpose.”', 'Ask what they get from it. If they’re posting their own abuse or injuries for the aesthetic, they need a person, not a tag.', '“Is that a style you like, or a place you go when things are bad?”', 'Mental Well-being', 'discuss'),
  t('bbl', 'bbl', ['brazilian butt lift', 'bbl body', 'bbl comment'], 'Brazilian butt lift, a surgical fat transfer. Also a 2024 song insult that teens quote without meaning surgery.', 'Body comments, plastic surgery, and a Drake/Kendrick lyric collided. Assume the lyric until the sentence is about procedures, money, or “she got it done.”', ['Quoting a song or a meme.', 'Gossip about plastic surgery.', 'A teen talking about wanting surgery. Slow down.'], '“The audio is the BBL one, not a medical plan.”', 'Lyrics are everywhere. Wanting surgery, hiding consultations, or mocking someone’s body are the live issues.', '“Are you quoting the song, or talking about an actual surgery?”', 'Social Media Culture', 'discuss'),
  t('ozempic', 'ozempic', ['ozempic face', 'semaglutide', 'the shot for weight'], 'A diabetes drug widely talked about for weight loss, including by people who don’t need it.', 'Teens hear it as a shortcut and as a punchline about celebrities’ faces. Unprescribed use, sharing pens, and “you need Ozempic” comments are the problems.', ['Celebrity gossip.', 'A joke about someone’s body. That’s cruelty.', 'Interest in getting it without a doctor.'], '“They said she has Ozempic face.”', 'Body-shaming plus a prescription drug is a health and kindness issue. No sourcing talk. If they’re trying to obtain it, involve a clinician, not a group chat.', '“That drug is a real medication. Are people at school treating it like a joke or like a plan?”', 'Substances & Party Culture', 'attention'),
  t('fake natty', 'fake-natty', ['natty', 'natural lifter', 'fake natural'], 'Someone who claims their muscles are natural while likely using steroids or other enhancers.', 'GymTok argues about this constantly. “Natty” means natural. The culture pushes teens to distrust every body and sometimes to “catch up.”', ['Sports gossip.', 'Insecurity about their own progress.', 'A doorway into steroid talk.'], '“Nobody gets that big natty in a year.”', 'Training is good. Drug rumors and shortcuts are the conversation. Don’t speculate about a classmate’s body with them.', '“What does your feed say you should be able to look like, and how fast?”', 'Substances & Party Culture', 'discuss'),
  t('nepo baby', 'nepo-baby', ['nepotism baby', 'nepo'], 'A celebrity or classmate who got ahead because of a parent’s connections.', 'A critique of unfair advantage. Also a lazy insult. Teens apply it to school roles, not just Hollywood.', ['Media literacy about fame.', 'Resentment at a cast list or team.', 'A joke that erases someone’s actual work.'], '“She got the lead and the comments just say nepo baby.”', 'Unfairness is worth discussing. So is reducing a person to their parents.', '“Where’s the line between help from family and something unfair?”', 'Social Media Culture', 'harmless'),
  t('industry plant', 'industry-plant', ['industry planted', 'planted artist'], 'An accusation that a new artist was secretly backed by a company and only pretends to be independent.', 'Fandom detective work. Sometimes insightful, often a rumor used to tear down a new favorite.', ['A theory about a musician.', 'Gatekeeping: “you’re not a real fan.”', 'A joke.'], '“People say she’s an industry plant because the video is too good.”', 'Ask what evidence would even count. It’s a lesson in rumors.', '“What would prove that, and why does it matter to the music?”', 'Social Media Culture', 'harmless'),
  t('benching', 'benching', ['benched', 'put me on the bench', 'dating bench'], 'Keeping someone as a backup while you date or talk to others.', 'Sports metaphor. The person on the bench gets occasional texts so they don’t move on. It feels confusing on purpose.', ['A pattern they suspect from a crush.', 'Advice-column language.', 'Something they realize they did to someone else.'], '“He only texts at midnight. I’m benched.”', 'You can talk about honesty and about not waiting in the dark. Avoid detective work on the other kid’s phone.', '“What would a clear answer from them look like?”', 'Relationships & Dating', 'discuss'),
  t('cushioning', 'cushioning', ['cushions', 'backup crush', 'cushioning me'], 'Keeping backup crushes warm in case the main person doesn’t work out.', 'A step beside benching. Flirty maybe-texts with several people while appearing committed or almost committed.', ['Ordinary “talking to more than one person” before anything is exclusive.', 'Stringing people along.', 'A word they learned from a video, not a situation they’re in.'], '“Cushioning is weird if you already said you were exclusive.”', 'Exclusivity is the hinge. Before that, people do talk to more than one person. Lying about it is the problem.', '“Did anyone actually agree to be exclusive?”', 'Relationships & Dating', 'discuss'),
  t('roster', 'roster', ['the roster', 'on his roster', 'dating roster'], 'The list of people someone is flirting with or seeing at the same time.', 'Sounds like a sports lineup. It treats partners as slots. Teens use it as a joke and as a real description.', ['A joke about having options.', 'Non-exclusive dating.', 'Cheating, if a commitment already exists.'], '“His roster is three people and none of them know.”', 'Secrecy plus a promise of exclusivity is the harm. A single crush is not a roster.', '“Is there an agreement, or a list nobody agreed to?”', 'Relationships & Dating', 'discuss'),
  t('hookup', 'hookup', ['hooked up', 'hooking up', 'hook-up'], 'A sexual or intensely physical encounter, often without a relationship. Sometimes people use it loosely for kissing.', 'The word is slippery on purpose. Adults hear sex. Teens sometimes mean a makeout. Ask what they mean without assuming the maximum.', ['Kissing.', 'A sexual encounter.', 'A rumor that may be exaggerated or false.'], '“They hooked up at the party, whatever that means.”', 'Rumors travel faster than facts. If your child is talking about pressure, safety, or regret, stay with that. Skip the interrogation tone.', '“When your friends say hookup, what do they actually mean?”', 'Relationships & Dating', 'attention'),
  t('sexting', 'sexting', ['sext', 'sexted', 'spicy texts'], 'Sexual messages or images sent by text or chat.', 'Common as a word, risky in practice. Photos of minors are child sexual abuse material even if a minor sent their own. Pressure, leaks, and adult senders change the emergency level.', ['Flirting that stayed in words between peers.', 'Photos sent under pressure.', 'An adult in the chat. That is a safety emergency, not a punishment moment.'], '“He asked me to sext and I didn’t answer.”', 'Lead with safety and a way out. If images exist, don’t spread them further, including to yourself “to check.” Get help from a trusted adult pathway or a reporting service.', '“You can tell me if someone is pushing for pictures. You won’t be in trouble for telling me.”', 'Sensitive Safety Topics', 'attention'),
  t('dick pic', 'dick-pic', ['dic pic', 'unsolicited pic', 'sent a pic of it'], 'A photo of a penis, often sent without being asked.', 'Teens send and receive these. Unsolicited ones are harassment. Photos of anyone under 18 are a legal problem, not a joke to forward.', ['A complaint about a picture they didn’t want.', 'Pressure to send one back.', 'A rumor or a forwarded image. Don’t forward it again.'], '“Some random sent a dick pic and I blocked him.”', 'Blocking and telling a trusted adult is the right instinct. If the sender is an adult or the image is of a minor, report. Don’t ask them to show you the picture.', '“You did the right thing blocking. Was it a stranger, and do you want help reporting it?”', 'Sensitive Safety Topics', 'attention'),
  t('baddie', 'baddie', ['baddies', 'she’s a baddie', 'baddie energy'], 'A confident, attractive person, often styled in a glamorous, hyper-feminine way.', 'A compliment and a costume. It can celebrate confidence or reduce people to a look. Not “bad” as in evil.', ['Praise for style or confidence.', 'A beauty standard.', 'Caption culture and filters.'], '“She walked in full baddie and the hallway noticed.”', 'Compliments are fine. Ranking girls and demanding the look every day is the pressure.', '“Is baddie a compliment you want, or a job description?”', 'Relationships & Dating', 'discuss'),
  t('player', 'player', ['he’s a player', 'playing her', 'player behavior'], 'Someone who dates or flirts with many people and isn’t honest about it.', 'An old word that never left. Sometimes a brag, sometimes a warning.', ['A reputation, true or not.', 'A joke.', 'A pattern of lying to partners.'], '“Don’t catch feelings, he’s a player.”', 'Reputations can be gossip. Lying and disrespect are the behaviors to name.', '“What did he actually do, separate from the label?”', 'Relationships & Dating', 'discuss'),
  t('exclusive', 'exclusive', ['we’re exclusive', 'not exclusive', 'exclusivity'], 'An agreement not to see other people. The step before, or instead of, a public relationship label.', 'Teens negotiate this awkwardly. Assuming exclusivity without saying it causes a lot of pain.', ['A clear agreement.', 'One person thinks it’s exclusive and the other doesn’t.', 'A label they want and are afraid to ask for.'], '“I thought we were exclusive. He didn’t.”', 'This is a communication skill, not a scandal. You can help them ask a clear question.', '“What did each of you actually say out loud?”', 'Relationships & Dating', 'discuss'),
  t('insta official', 'insta-official', ['instagram official', 'posted them', 'made it insta official'], 'Making a relationship public by posting the person.', 'Overlaps with hard launch, which this library already covers. “Insta official” is the status change in the friend group, not just the post.', ['A mutual, happy post.', 'Pressure to post before they’re ready.', 'A post used as proof in a later argument.'], '“She won’t be insta official and he’s spiraling.”', 'A post is not a contract. Refusal to post is not proof of shame. Talk about pace.', '“Does official mean a conversation, or a photo?”', 'Relationships & Dating', 'discuss'),
  t('slow fade', 'slow-fade', ['fading', 'faded out', 'soft ghost'], 'Ending contact gradually instead of saying it’s over.', 'Less abrupt than ghosting, and often more confusing. Replies get shorter, slower, then stop.', ['A mutual loss of interest.', 'Someone avoiding a hard conversation.', 'Anxiety while they watch the gap grow.'], '“He’s slow fading. Yesterday was one word.”', 'You can coach a direct sentence and also coach them not to chase forever.', '“Do you want a clear answer, or are you okay letting it fade?”', 'Relationships & Dating', 'discuss'),
  t('boo', 'boo', ['my boo', 'boo’d up', 'boos'], 'A romantic partner. “Boo’d up” means coupled.', 'Affectionate and a little old-school, still everywhere in lyrics and captions.', ['A partner.', 'A crush they’re joking about.', 'A song lyric.'], '“My boo made the team.”', 'Usually sweet. Ask who, the way you’d ask about any partner, without mocking the word.', '“Tell me about your boo—how long have you been together?”', 'Relationships & Dating', 'harmless'),
  t('bae', 'bae', ['my bae', 'bae goals'], 'A partner or beloved person. From “before anyone else,” or just “babe.”', 'Slightly dated and still used, often ironically. Pets and best friends get the label too.', ['A partner.', 'Ironic affection for a friend or a snack.', 'A caption.'], '“Bae is the leftover pizza.”', 'Check the noun. Pizza is not a secret relationship.', '“Is bae a person or a joke?”', 'Relationships & Dating', 'harmless'),
  t('pull', 'pull', ['pulled', 'on the pull', 'did you pull'], 'In UK and internet slang, to attract someone or kiss or go home with them.', '“Did you pull?” after a party means “did you get with anyone?” The exact act varies. In other sentences, pull just means to draw or to leave.', ['Flirting success.', 'A kiss or more. Ask before you fill in the blank.', 'Ordinary English: pull a door, pull up to a place.'], '“He thinks he pulled and she thinks they just talked.”', 'Party gossip exaggerates. Consent and sobriety are the serious layers, not the slang trophy.', '“When your friends say pull, what are they counting?”', 'Relationships & Dating', 'discuss'),
  t('negative rizz', 'negative-rizz', ['neg rizz', 'L rizz', 'rizzless'], 'Flirting so badly it repels people. The opposite of rizz.', 'A joke diagnosis. Sometimes fond, sometimes a way to humiliate a clumsy kid.', ['Self-roast.', 'Teasing a friend.', 'Ranking people by romantic worth.'], '“I waved and said hey guys. Negative rizz.”', 'The joke is fine until someone believes they’re unlovable. That’s the moment to be a person, not a critic.', '“Is negative rizz a funny story or a feeling you’re stuck with?”', 'Relationships & Dating', 'harmless'),
  t('seeing someone', 'seeing-someone', ['we’re seeing each other', 'seeing him', 'seeing her'], 'Dating without a firm public label. More than talking, less than “partner” for some teens.', 'Intentionally vague. It can be a real relationship or a way to avoid the DTR talk.', ['An early relationship.', 'A way to dodge exclusivity.', 'A clear, mutual dating situation that just isn’t online.'], '“I’m seeing someone. No, I’m not posting it.”', 'Privacy is allowed. Vagueness that hurts the other person is a kindness conversation.', '“What does seeing someone mean for the two of you?”', 'Relationships & Dating', 'discuss'),
  t('cheated on', 'cheating', ['cheated on me', 'he cheated', 'microcheating'], 'Breaking a relationship agreement. Teens also argue about “microcheating”: likes, streaks, and DMs.', 'The agreement matters. You can’t cheat a relationship that was never exclusive, but you can still lie. Microcheating debates get intense online.', ['A clear betrayal of an agreement.', 'A rumor.', 'A fight about likes and follows that may not match your values, but matters to them.'], '“She called it cheating because he kept a Snap streak.”', 'Don’t laugh them out of the feeling. Do help them separate a broken promise from a vague, unlabeled arrangement.', '“What had you two promised each other?”', 'Relationships & Dating', 'discuss'),
  t('spicy', 'spicy', ['it’s spicy', 'spicy book', 'spicy chat'], 'A cute label for sexual content. In food, it still means hot pepper.', 'BookTok and chats use spicy so they don’t say sexual. The content may still be explicit.', ['A seasoned snack. Really.', 'A romance novel with sex scenes.', 'A conversation that turned sexual.'], '“The book is spicy so don’t read it out loud.”', 'Ask what spicy includes. You can set household limits on explicit media without acting shocked that the word exists.', '“Spicy like peppers, or spicy like sex scenes?”', 'Relationships & Dating', 'discuss'),
  t('hard to get', 'hard-to-get', ['playing hard to get', 'play hard to get'], 'Acting less interested than you are, as a tactic.', 'Advice videos still push this. It often confuses everyone and rewards game-playing over honesty.', ['A joke about not texting back.', 'Advice they are trying.', 'Frustration that someone else is using it on them.'], '“The video said play hard to get. I hate it.”', 'You can back honesty. Mixed signals are already in this library for the receiving end.', '“Would you rather be clear and risk a no?”', 'Relationships & Dating', 'discuss'),
  t('age gap', 'age-gap', ['age-gap relationship', 'big age gap', 'older guy'], 'A romance where the ages are far enough apart to raise a power question.', 'Some gaps between older teens are clumsy but mutual. An adult and a minor is not a quirky trope. It is a safety problem.', ['Two teens a year or two apart. Often ordinary.', 'A teen romanticizing a much older person online.', 'An adult pursuing a minor. Act on that.'], '“He’s older but it’s an age-gap thing, it’s fine.”', 'Ask numbers. “Older” can mean 17 or 27. You need the number, calmly, without calling your child the problem.', '“When you say older, how old are each of you?”', 'Sensitive Safety Topics', 'attention'),
  t('outed', 'outed', ['outing', 'got outed', 'outed him'], 'Revealing someone’s sexuality or gender without their permission.', 'A serious harm even when the reveal is “true.” Teens also say “outed” loosely for any exposed secret. Identity is the meaning to treat with care.', ['A secret of any kind was exposed.', 'Someone’s LGBTQ+ identity was shared without consent.', 'A fear that it will happen.'], '“Don’t joke about outing people. That’s not your story.”', 'If it already happened, the target needs support and a plan for school, not a debate about whether the identity is okay.', '“Did someone share a secret that wasn’t theirs? How is that person doing?”', 'Sensitive Safety Topics', 'attention'),
  t('deadname', 'deadname', ['deadnamed', 'dead name', 'using their deadname'], 'A transgender person’s former name, used instead of the name they use now.', 'Using it by mistake is a moment to correct and move on. Using it on purpose is hostility. The word “dead” is intense because the old name is something they’ve left.', ['A mistake they feel bad about.', 'Harassment.', 'Explaining the concept.'], '“The sub list deadnamed her and the class went quiet.”', 'Use the current name. You don’t need the old one repeated in conversation to take this seriously. Schools can fix rosters.', '“What name should we be using, and do you want help fixing where the old one still shows up?”', 'Sensitive Safety Topics', 'discuss'),
  t('binder', 'binder', ['chest binder', 'binding', 'my binder'], 'A compression garment some trans and gender-nonconforming people wear to flatten the chest.', 'Not a sexual term. It is gender expression and dysphoria care. Unsafe binding (ace bandages, sleeping in a too-small binder) can hurt ribs and breathing. You can care about safety without making it a fight about identity.', ['A piece of clothing they or a friend uses.', 'A health question about pain or breathing.', 'Gossip that outs someone. Don’t participate.'], '“The binder hurts after band.”', 'Pain is a practical problem. Offer a better-fitting option, breaks, and a clinician if there’s pain. Skip the identity debate in the same breath as the pain.', '“Thank you for telling me it hurts. Can we find a safer way so you can breathe and still feel like yourself?”', 'Mental Well-being', 'discuss'),
  t('passing', 'passing', ['he passes', 'clocked vs passing', 'doesn’t pass'], 'Being read as the gender someone is, without being questioned. Also an ordinary word for handing something over or a hall pass.', 'In gender conversations, “passing” can be a relief or a painful standard. “Doesn’t pass” is often used cruelly.', ['School hall-pass talk. Ordinary.', 'A trans person describing safety or joy.', 'A cruel ranking of someone’s body.'], '“I need a pass to the nurse. Also, they were ranking who ‘passes.’ That part was ugly.”', 'Hall passes are logistics. Ranking trans bodies is harassment. Keep those sentences apart.', '“Were they talking about a hall pass, or about someone’s gender?”', 'Social Media Culture', 'discuss'),
  t('derealization', 'derealization', ['derealised', 'nothing feels real', 'drdp'], 'The world feels unreal, foggy, or like a simulation.', 'A dissociative experience teens now have language for. It can happen with panic, sleep loss, or trauma. It can also be a word they learned from a video and are trying on.', ['A scary but known anxiety symptom.', 'A metaphor for a weird day.', 'Ongoing episodes that frighten them.'], '“In the hallway everything looked fake. I think it was derealization.”', 'Don’t argue them out of the feeling. If it’s intense, frequent, or comes with hopelessness, a professional is appropriate. You can stay steady.', '“When the world feels unreal, how long does it last, and what helps you come back?”', 'Mental Well-being', 'discuss'),
  t('depersonalization', 'depersonalization', ['dpdr', 'I don’t feel real', 'outside my body'], 'Feeling detached from your own body or self, as if you’re watching yourself.', 'Often paired with derealization. Panic, exhaustion, and trauma are common contexts. TikTok also spreads the label faster than support.', ['A one-off during panic.', 'A word they heard and are checking against their experience.', 'A recurring state that needs care.'], '“I got depersonalized during the test and my hands didn’t feel like mine.”', 'Believe the distress. Grounding, sleep, and a clinician if it repeats. Avoid true-crime energy.', '“That sounds frightening. Has it happened more than once?”', 'Mental Well-being', 'discuss'),
  t('maladaptive daydreaming', 'maladaptive-daydreaming', ['madd', 'daydreaming disorder', 'can’t stop daydreaming'], 'Vivid daydreams that eat hours and get in the way of school, sleep, or relationships.', 'Different from a healthy imagination. Teens use the label when stories feel compulsive. It is not an official diagnosis everywhere, and the struggle can still be real.', ['A rich fantasy life that is still a choice.', 'Hours lost and falling grades or sleep.', 'A coping tool that outgrew its job.'], '“I pace and daydream for hours. It’s not just zoning out.”', 'Don’t confiscate imagination. Do take impairment seriously: sleep, school, distress. A counselor helps more than a ban on thinking.', '“When the stories take over, what are they giving you that the day isn’t?”', 'Mental Well-being', 'discuss'),
  t('gifted kid burnout', 'gifted-kid-burnout', ['former gifted kid', 'gifted kid syndrome'], 'The crash after years of being praised for being smart, then hitting work that requires new skills.', 'A very common teen identity online. Perfectionism, shame, and “if I can’t do it instantly I’m a fraud.” Sometimes tied to undiagnosed learning or attention differences. Sometimes just a hard year.', ['A meme they relate to.', 'Real shame about grades.', 'A story that explains avoidance.'], '“Former gifted kid and this worksheet is winning.”', 'Separate their worth from speed. Offer process, rest, and help. Don’t add “but you’re smart” as the fix. They’ve heard it.', '“When something isn’t instant, what do you tell yourself it means about you?”', 'Mental Well-being', 'discuss'),
  t('rsd', 'rsd', ['rejection sensitive dysphoria', 'rejection sensitivity'], 'An intense pain response to real or imagined rejection, often discussed in ADHD communities.', 'A small criticism can feel like a catastrophe. The term helps some teens name it. It can also become a reason they never hear feedback.', ['A useful name for a huge reaction.', 'Something they’re exploring after a video.', 'A shield against any accountability. You can validate the pain and still keep the boundary.'], '“I know it’s RSD but the comment ruined my night.”', 'Name the feeling, don’t litigate whether the term is official, and don’t remove every limit. Both the pain and the behavior can be real.', '“The feeling sounds huge. What do you need while it’s loud, and what still has to be repaired?”', 'Mental Well-being', 'discuss'),
  t('self-dx', 'self-dx', ['self diagnosed', 'self dx', 'I’m pretty sure I have it'], 'Deciding you have a condition without a formal evaluation.', 'Teens do this with ADHD, autism, anxiety, and more, often because care is hard to get or because a video fit. It can lead to insight or to a stuck identity built on a 40-second clip.', ['A step toward asking for a real evaluation.', 'Language that helps them find peers.', 'A firm belief that shuts down other explanations.'], '“I self-dx’d after the term matched too well.”', 'Don’t mock it. Offer a proper evaluation if they want one, and support the struggles whether or not a label arrives.', '“Which parts are getting in your way? We can get those looked at properly.”', 'Mental Well-being', 'discuss'),
  t('audhd', 'audhd', ['auadhd', 'autism and adhd', 'audhd’er'], 'A casual term for having both autism and ADHD.', 'Common in online neurodivergent communities. Some users are diagnosed, some are self-identified. The struggles they describe—sensory load, focus, social fatigue—can be real either way.', ['A diagnosis they have.', 'A community identity.', 'A guess. Treat the needs, and offer assessment if they want it.'], '“My AuDHD makes the cafeteria feel like a siren.”', 'Practical help beats label debates: headphones, breaks, clear instructions. You can still pursue an evaluation.', '“What would make the cafeteria survivable tomorrow?”', 'Mental Well-being', 'discuss'),
  t('shutdown', 'shutdown', ['autistic shutdown', 'I shutdown', 'shut down mode'], 'Going quiet and stuck when overwhelmed, rather than exploding.', 'Different from a meltdown, which is louder. Shutdowns get missed because the kid looks “fine” or “rude.” Also ordinary English for a computer or a building.', ['A response to sensory or social overload.', 'Exhaustion after masking.', 'A laptop. Check the sentence.'], '“I wasn’t ignoring you. I shutdown after the assembly.”', 'Lower the input. Don’t demand eye contact and a full debrief in the moment. Talk later.', '“When you go quiet like that, what’s the most helpful thing I can do?”', 'Mental Well-being', 'discuss'),
  t('meltdown', 'meltdown', ['autistic meltdown', 'had a meltdown', 'meltdown not tantrum'], 'An overwhelm response: crying, yelling, or losing control because the nervous system is overloaded. Not a planned tantrum.', 'Teens use it for neurodivergent overload and, more loosely, for any big cry. The precise meaning matters less than helping them recover and looking at triggers.', ['Sensory or social overload.', 'A loose word for a hard cry.', 'Shame after they “lost it.”'], '“The fire drill was a meltdown, not me being dramatic.”', 'Safety first, lecture later, shame never. Look at sleep, noise, hunger, and demands.', '“What was the last straw, and what helps you come back?”', 'Mental Well-being', 'discuss'),
  t('hyperfocus', 'hyperfocus', ['hyper focused', 'locked in focus', 'hyperfocusing'], 'Intense focus on one thing that is hard to pull out of, often discussed with ADHD.', 'Different from hyperfixation, which this library already has as a lasting interest. Hyperfocus is the in-the-zone state that can erase time.', ['A useful burst on a project.', 'Missing meals, sleep, or someone talking.', 'A word they’re trying on.'], '“I hyperfocused and the whole evening disappeared.”', 'Protect food, sleep, and transitions. Don’t only praise the productivity.', '“How do you want me to interrupt you when the focus eats the evening?”', 'Mental Well-being', 'harmless'),
  t('infodump', 'infodump', ['info dump', 'infodumping', 'let me infodump'], 'Sharing a lot of specialized information at once, with enthusiasm.', 'Often a joy, especially around a special interest. The listener’s job is sometimes just to receive it. It becomes hard when they can’t tell nobody consented to a 40-minute monologue.', ['A happy share.', 'A bid for connection.', 'A moment they later fear was “too much.”'], '“Can I infodump about the update or are you busy?”', 'That question in the example is the skill. Encourage the interest and the check-in.', '“I have ten minutes for a full infodump. Go.”', 'Mental Well-being', 'harmless'),
  t('special interest', 'special-interest', ['spinterest', 'spin', 'current spin'], 'A deep, lasting interest that brings joy and regulation, especially in autistic communities.', 'Not “just a phase” and not a problem to prune. Spinterest is a cutesy online shortening. Problems start when the interest is forbidden, or when it’s the only allowed topic and friendships strain.', ['A beloved subject.', 'A regulation tool.', 'Something they’re ashamed of liking.'], '“My special interest is transit maps and I will not be taking questions. I will be taking questions.”', 'Ask to be taught. Shame around interests pushes them underground.', '“Teach me the part you think I’d actually get.”', 'Mental Well-being', 'harmless'),
  t('safe food', 'safe-food', ['safe foods', 'fear food', 'samefood'], 'A food that feels predictable and okay to eat. Fear foods are the ones that don’t.', 'Used around ARFID, autism, and eating disorders. Samefood means eating the same thing repeatedly because it is regulating. This can be sensory, not “picky,” and it can also hide restriction.', ['A sensory preference.', 'A short list that keeps them fed during stress.', 'A shrinking list plus fear, weight talk, or rules. Get help.'], '“I can do the usual safe food tonight. The new thing is a no.”', 'Keep them fed with the foods that work, and get curious if the list is collapsing or tied to calorie fear. Don’t surprise-plate them as a test.', '“What’s on the safe list this month, and is anything getting harder?”', 'Mental Well-being', 'discuss'),
  t('sleepmaxxing', 'sleepmaxxing', ['sleep maxxing', 'mouth tape', 'sleep stack'], 'Treating sleep like a hack to optimize: gadgets, supplements, mouth tape, strict rules.', 'Some of it is ordinary good sleep. Some of it is expensive nonsense or physically risky, like taping a mouth shut or taking random supplements. The “maxxing” framing comes from the same world as looksmaxxing.', ['A reasonable bedtime push.', 'Buying a stack of products.', 'Risky tricks copied from a video.'], '“The video said mouth tape will change my face and my sleep.”', 'Back a boring bedtime. Be skeptical of tape, unprescribed supplements, and face-changing promises. A doctor if there’s real insomnia or breathing trouble.', '“Let’s get the basics honest—phone, caffeine, bedtime—before any gadget from a video.”', 'Mental Well-being', 'discuss'),
  t('75 hard', '75-hard', ['75hard', 'the 75 hard challenge'], 'A strict 75-day program: two workouts a day, a diet, a gallon of water, daily progress photos, no alcohol, no rest days.', 'It circulates as discipline content. For teens it can mean overtraining, hidden food rules, and body photos. Missing one day “resets” the whole thing, which feeds all-or-nothing thinking.', ['A short-lived fitness burst.', 'A peer challenge.', 'Injury, exhaustion, or food rules. Step in.'], '“If I miss day 12 I have to start over. That’s the rule.”', 'You can value fitness and reject a program with no rest and with body-check photos. Offer a saner plan.', '“What happens to your body on a day it needs rest?”', 'Mental Well-being', 'discuss'),
  t('narcissist', 'narcissist', ['narc', 'he’s a narcissist', 'narcissistic abuse'], 'A clinical personality pattern, and a word teens now use for any selfish or hurtful person.', 'Sometimes a serious description of manipulation. Often a video-diagnosis of a parent, ex, or classmate after one bad day. Both the harm and the overuse matter.', ['Accurate recognition of a painful pattern.', 'A label from a 30-second video.', 'A way to end a relationship story without more detail.'], '“My lab partner is a narcissist because he took credit.”', 'Don’t fight the word first. Ask what happened. If there’s control, fear, or isolation, stay on those facts. If it’s one rude moment, say so without mocking their hurt.', '“What did they do, step by step, separate from the label?”', 'Mental Well-being', 'discuss'),
  t('so OCD', 'so-ocd', ['i’m so ocd', 'ocd about it', 'obsessive'], 'A casual, usually inaccurate way to say “I like things neat.” Real OCD is distressing intrusive thoughts and compulsions, not a preference for tidy notes.', 'The casual use minimizes a real disorder. Some teens are also trying to describe actual symptoms and only have this phrase.', ['A tidy preference. Not OCD.', 'A joke.', 'Real symptoms: intrusive thoughts, rituals, distress, lateness because of checking. Take that seriously.'], '“I’m so OCD about my highlighters.”', 'You can correct the casual use gently and still ask if there’s a worry they can’t drop. Real OCD deserves care, not a punchline.', '“Do you mean you like it neat, or is there a worry that won’t let go?”', 'Mental Well-being', 'discuss'),
  t('bipolar', 'bipolar-casual', ['so bipolar', 'the weather is bipolar', 'you’re bipolar'], 'A real mood disorder, and a slur-like joke for any changeable person or even the weather.', 'Casual use is inaccurate and stigmatizing. Actual bipolar disorder is not “annoyed at lunch and fine at dinner.” If they are describing extreme swings, sleepless energy, and crashes, listen for the real thing.', ['A careless insult or joke.', 'Confusion about their own moods.', 'Symptoms that need a professional, especially sleepless high-energy stretches.'], '“The group chat is so bipolar today.”', 'Ask them to pick a more precise word for ordinary moodiness. If the description includes days without sleep and risky behavior, call a clinician.', '“When you say bipolar, do you mean moody, or something that lasts for days and changes sleep?”', 'Mental Well-being', 'discuss'),
  t('pda', 'pda', ['public display of affection', 'demand avoidance', 'pathological demand avoidance'], 'Either public affection, or a profile where everyday demands trigger intense avoidance.', 'You need the sentence. Kissing in the hallway is the old meaning. In neurodivergent spaces, PDA is a nervous-system “no” to demands, even demands the person agrees with. Both are real teen topics.', ['Couples being affectionate at school.', 'A student who melts down when told to start, even on things they want.', 'A label from a video.'], '“PDA in the hallway is a lot. Also, my counselor mentioned demand avoidance, which is a different PDA.”', 'Don’t assume. Ask which one. Demand avoidance needs collaboration, not louder orders. Hallway affection needs whatever boundary your family actually holds.', '“Which PDA is this—affection in public, or the demand thing?”', 'Mental Well-being', 'discuss'),
  t('people pleaser', 'people-pleaser', ['people pleasing', 'i can’t say no', 'fawn'], 'Someone who says yes, smooths conflict, and hides their needs to stay liked or safe.', 'Related to fawning, already in this library. Insight is useful. The identity can also become “so I never have to say what I want.”', ['A real pattern they’re tired of.', 'A compliment they don’t want anymore.', 'A reason they take on too much.'], '“I’m a people pleaser and I signed up for three committees.”', 'Practice one small no with backup. Don’t pathologize kindness.', '“Where could a small no happen this week, and I’ll back you?”', 'Mental Well-being', 'discuss'),
  t('impostor syndrome', 'impostor-syndrome', ['imposter syndrome', 'i’m a fraud', 'they’ll find out'], 'The belief that your success is a fluke and you will be exposed as a fraud.', 'Common in high-achieving teens. Sometimes it’s this feeling. Sometimes they are actually in over their head and need help, not a pep talk.', ['A feeling that ignores real evidence.', 'A cue they need support or a smaller load.', 'A phrase they learned and are testing.'], '“I got in and now the impostor thing is loud.”', 'Show specific evidence without toxic positivity. Also check whether the load is actually impossible.', '“What part feels like a fraud, and what part is just new?”', 'Mental Well-being', 'discuss'),
  t('big sad', 'big-sad', ['the big sad', 'it’s the big sad'], 'A soft, half-joking name for feeling depressed or deeply down.', 'The cuteness lets them say it. Don’t let the cuteness make you miss it. It can be a passing mood or a bid for help.', ['A bad day, said gently.', 'A recurring low mood.', 'A way to test whether you’ll take it seriously.'], '“It’s the big sad tonight. I don’t want advice.”', 'Follow their request: company or quiet, not a fix lecture. If the big sad is most days, widen the support.', '“I’m here. Do you want company, quiet, or help finding more support?”', 'Mental Well-being', 'discuss'),
  t('in shambles', 'in-shambles', ['shambles', 'my life is in shambles', 'we’re in shambles'], 'Falling apart. Often comic exaggeration, sometimes not.', 'Used for a ruined grade, a messy room, a breakup, or a group chat after news. The scale is in the details.', ['A joke about a small disaster.', 'Real overwhelm.', 'Group drama.'], '“My notes are in shambles.”', 'Laugh if they are. Stay if the next sentence is about hopelessness.', '“Shambles like a messy binder, or shambles like you’re not okay?”', 'Mental Well-being', 'harmless'),
  t('sadge', 'sadge', ['sadge moment', 'pepe sad', 'feels sadge'], 'A gamer way to say sad. From a crying cartoon face used in chats.', 'Milder and more meme than “I’m depressed,” but people use it when they’re actually down too.', ['A loss in a game.', 'A small real disappointment.', 'A lightweight way to say they feel low.'], '“We threw the match. Sadge.”', 'You can match the lightness and still offer a real check.', '“Sadge at the game, or sadge at the day?”', 'Gaming & Streaming', 'harmless'),
  t('relapse', 'relapse', ['relapsed', 'in relapse', 'recovery and relapse'], 'Going back to self-harm, disordered eating, or substance use after a stretch without it.', 'A serious word. Teens also use it loosely for “I downloaded the app again.” If the context is harm, treat it as harm. Shame makes the next relapse quieter.', ['A return to self-harm or an eating disorder.', 'A return to substance use.', 'A dramatic word for breaking a minor streak. Confirm which.'], '“I relapsed last night and I didn’t want to hide it.”', 'Thank them for saying it. Safety first, then a professional if you don’t already have one. Don’t make honesty expensive.', '“Thank you for telling me. Are you safe tonight, and who else should be in this with us?”', 'Mental Well-being', 'attention'),
  t('5150', '5150', ['5150 hold', 'psych hold', 'baker acted'], 'In California, a short involuntary psychiatric hold. Online, teens use “5150” loosely for any crisis hospitalization.', 'The number is a legal code, not a personality. Other states have other numbers. Teens may mean “someone was hospitalized for safety,” or they may be joking. Jokes still tell you the topic is in the room.', ['A reference to a show, song, or meme.', 'A real hospitalization, theirs or a friend’s.', 'Fear that if they speak up they’ll be “5150’d.” That fear keeps people quiet.'], '“I’m not gonna get 5150’d for saying I’m sad, right?”', 'Answer the fear. Crisis care exists to keep people alive, and most sadness does not lead to a hold. If they’re unsafe, you still act. Explain the difference calmly.', '“Saying you’re sad is not the same as a forced hospital stay. I do want to know if you’re thinking about hurting yourself.”', 'Mental Well-being', 'attention'),
  t('doomposting', 'doomposting', ['doompost', 'doomer posting', 'doomer'], 'Posting that everything is ruined: the climate, the future, their life, the world.', 'Related to doomscrolling, which is already in this library. Doomposting is when they join in. It can be gallows humor or a sink into hopelessness.', ['A joke among friends.', 'Real anxiety about the future.', 'A feed that only rewards despair.'], '“The group chat is just doomposting tonight.”', 'Don’t fake optimism. Do ask what they can touch that isn’t the feed: one person, one plan, one boundary with the app.', '“How do you feel after an hour of that chat?”', 'Mental Well-being', 'discuss'),
  t('manifest', 'manifest', ['manifesting', 'manifestation', 'I manifested it'], 'Willing something to happen by visualizing or declaring it.', 'A huge trend. Sometimes it’s goal-setting with mystical branding. Sometimes it blames people for not “vibrating” their way out of real problems.', ['A hopeful habit.', 'A joke.', 'Self-blame when something awful happens anyway.'], '“I manifested the test being moved and it wasn’t. Rude.”', 'Encourage agency. Push back gently on the idea that victims failed to think positively enough.', '“What part is a wish, and what part is a plan you can actually do?”', 'Mental Well-being', 'harmless'),
  t('lucky girl syndrome', 'lucky-girl-syndrome', ['lucky girl', 'i’m so lucky'], 'Declaring that you are lucky so that good things will follow.', 'A 2023-and-after manifestation variant. Cute until it becomes denial or debt.', ['A gratitude practice in costume.', 'A joke.', 'Ignoring real constraints because a video said luck is a mindset.'], '“Lucky girl syndrome says the bus will wait.”', 'You can enjoy confidence and still catch the bus with a clock.', '“I love the confidence. What’s the backup if the universe is late?”', 'Mental Well-being', 'harmless'),
  t('reality shifting', 'reality-shifting', ['shifting', 'shift to hogwarts', 'desired reality'], 'A belief, spread online, that you can move your consciousness into a chosen fictional or better reality, often through sleep techniques.', 'Mostly a daydream ritual. The risk is sleep loss, isolation, and preferring the scripted world so hard that this one stops mattering. It is not a proven ability. Don’t mock the longing underneath it.', ['A fandom sleep ritual.', 'A comfort when this world feels bad.', 'Skipping sleep and friends to “shift.” That’s the practical problem.'], '“I was up trying to shift and now I’m wrecked.”', 'Ask what they want in the other reality that they’re not getting here. Protect sleep. Get more help if this world feels unbearable.', '“What does that reality have that today doesn’t?”', 'Mental Well-being', 'discuss'),
  t('subliminals', 'subliminals', ['subliminal', 'subliminal audio', 'looks subliminal'], 'Audio or video that claims hidden messages can change your face, height, grades, or life while you listen.', 'A big corner of youth YouTube. There is no good evidence that whispering under music changes bone structure. The feeds often target body insecurity. Some “subliminals” are just affirmations. Some are scams or body-dysmorphia fuel.', ['A curiosity or a placebo mood boost.', 'Body-change promises. Those don’t deliver and can worsen obsession.', 'Hours of listening tied to looksmax or eating-disorder goals.'], '“The subliminal says it can change my nose in a week.”', 'You can be kind and clear: wishes aren’t surgery, and noses don’t move because of a soundtrack. Look at the insecurity the video is selling to.', '“What are you hoping will change, and who told you a video could do that?”', 'Social Media Culture', 'discuss'),
  t('villain era', 'villain-era', ['in my villain era', 'villain arc'], 'A chapter where they stop people-pleasing, or where they lean into being petty or cruel and call it growth.', 'Sometimes a healthy boundary with dramatic branding. Sometimes a justification for hurting people after being hurt.', ['Setting a boundary.', 'A joke about a minor petty choice.', 'Payback. Ask who gets hurt.'], '“Villain era means I’m not lending notes to people who never lend back.”', 'Support the boundary. Question the revenge if someone’s humiliation is the plan.', '“Is the villain era a boundary, or a plan to hurt someone?”', 'Mental Well-being', 'discuss'),
  t('elf bar', 'elf-bar', ['elfbar', 'elf bars', 'lost mary'], 'A popular brand of disposable nicotine vape. Lost Mary is a sibling brand teens name the same way.', 'Like Geek Bar, already in this library. Flavors and bright packaging are the point. Naming the brand often means the object is around, not always that they use it.', ['Gossip about what people hit at school.', 'A device they have seen or used.', 'A meme.'], '“The bathroom smells like elf bar again.”', 'Nicotine is the topic, whatever the logo is. Talk about addiction and school rules without a spy mission as the opening move.', '“Which brands are actually around at school?”', 'Substances & Party Culture', 'attention'),
  t('chroming', 'chroming', ['chrome', 'huffing', 'dusting'], 'Inhaling chemical fumes—deodorant, solvents, gas—to get high.', 'A dangerous trend name that resurfaced in parent warnings in the mid-2020s. The high is brief. The harm can include sudden death, even the first time. Do not share methods or “safer” ways. This is not a story for shock value. It is a medical emergency if you suspect it is happening.', ['A news story or a joke about a video.', 'Peer pressure at a party.', 'Supplies, smells, or rashes that need a direct question and, if use is happening, medical care.'], '“People were talking about chroming like it was funny.”', 'Say plainly that inhaling fumes can kill, including the first time, and that you will help if they’re scared a friend is doing it. No lectures that dare them. No instructions.', '“Have you seen anyone actually doing that, or only videos? If someone passes out, we call for help immediately.”', 'Substances & Party Culture', 'attention'),
  t('greening out', 'greening-out', ['greened out', 'greening', 'whitey'], 'Feeling sick, panicky, or faint after too much cannabis. “Whiteying” is a UK name for a similar crash.', 'Not a cute color story. Vomiting, spinning rooms, anxiety, and passing out can happen, especially with edibles whose dose arrives late. It can be frightening and, if mixed with other substances, dangerous.', ['A story about someone else at a party.', 'A video.', 'Your child or a friend going through it. Stay with them and get medical help if breathing, consciousness, or chest pain is involved.'], '“He greened out and they just left him in the yard.”', 'Leaving someone sick and alone is the failure mode. Talk about not ditching a friend and about edible dosing myths without giving a how-to.', '“If someone is that sick, what would you do in the first five minutes?”', 'Substances & Party Culture', 'attention'),
  t('fake id', 'fake-id', ['fake identification', 'fake license', 'borrowed id'], 'A false identification used to buy alcohol, get into venues, or pass an age gate.', 'Common in older teen talk. It is illegal. The practical risks include getting caught, owing money to whoever supplied it, and being in adult spaces.', ['Jokes and dares.', 'A plan.', 'Someone selling IDs to classmates. That’s a bigger problem.'], '“He says he can get a fake for fifty.”', 'Don’t help them make a better one. Do talk about the debt, the adult environments, and the fact that “everyone” is not a legal defense.', '“What happens if the person who sells it keeps your photo and your money?”', 'Substances & Party Culture', 'attention'),
  t('dirty 30', 'dirty-30', ['m30', 'pressed 30', 'dirty thirties'], 'A pill sold as a 30 mg oxycodone that is often counterfeit and may contain fentanyl.', 'This is one of the highest-risk drug phrases in teen circulation. “Blues” and “percs” can point here too. One counterfeit pill can be fatal. Do not describe how to identify, buy, or dose them. If you suspect use, treat it as a medical emergency and get naloxone guidance from a pharmacist or clinician, not from a chat.', ['A lyric.', 'A rumor about a party.', 'Pills in a backpack or a photo. Act.'], '“Someone was selling blues behind the gym.”', 'Use official, local resources for naloxone and poisoning emergencies. Tell your child that experimenting with pressed pills is not the same risk as a beer. No shame for asking for help.', '“If pills are going around, I need you alive more than I need you in trouble. What have you actually seen?”', 'Substances & Party Culture', 'attention'),
  t('fentanyl', 'fentanyl', ['fent', 'fent pressed', 'fentanyl test'], 'A powerful opioid. A medical drug, and the substance that makes many counterfeit pills and street drugs deadly.', 'Teens may mention it from the news, a health class, or a real supply. Awareness is good. Casual “it’s just a little” is not. Overdose can look like slow breathing and unresponsiveness. Call emergency services. Naloxone saves lives and is not a lecture.', ['News or a school lesson.', 'Fear about a friend’s pills.', 'Use or a suspected overdose. Get emergency help.'], '“Health class said fentanyl is in fake pills.”', 'Confirm they understood the lesson: you cannot see it, and it shows up in pills and powders sold as something else. If a friend is unconscious, they call for help first.', '“What did health class say to do if someone won’t wake up?”', 'Substances & Party Culture', 'attention'),
  t('ketamine', 'ketamine', ['ket', 'special k', 'k-hole'], 'A medical anesthetic that people also use as a club drug. A “k-hole” is a frightening, immobilized high.', 'It shows up in party talk and in memes. It is also a prescribed treatment in clinics, which is a different context. Street use risks vomiting, accidents, bladder damage, and mixing with alcohol.', ['A lyric or a news story.', 'Clinic treatment. That’s medical, not a party.', 'Party use. The setting and the mixing are the danger.'], '“They were joking about k-holes like it was a ride.”', 'Separate medical care from recreational use. Don’t describe doses or routes. If they’re around it, talk about not mixing and not leaving friends who can’t move.', '“Was that a joke, a headline, or something people are actually using?”', 'Substances & Party Culture', 'attention'),
  t('ghb', 'ghb', ['gbl', 'liquid g', 'liquid ecstasy'], 'A depressant liquid used recreationally and, too often, to incapacitate someone.', 'Small amounts have a steep effect. Mixing with alcohol is especially dangerous. It has a reputation in drink-spiking. If someone is suddenly far more impaired than what they drank, treat it as a medical emergency and don’t leave them.', ['A news story about spiking.', 'Party talk.', 'A friend who is unexpectedly unconscious. Get help and stay.'], '“The group chat said don’t leave drinks because of G.”', 'Back the instinct to watch drinks. Skip scare theater that skips first aid. Unconsciousness is an emergency call, not a secret.', '“If a friend suddenly can’t stay awake, what’s the first call you make?”', 'Substances & Party Culture', 'attention'),
  t('acid', 'acid', ['lsd', 'tab of acid', 'tripping on acid'], 'LSD, a hallucinogen. “Lucy” and “tabs” are common nicknames.', 'A tab is blotter paper. Effects last many hours and can include panic. “Bad trip” is not a punchline if someone is terrified. Don’t give dosing advice. Do talk about not mixing, not being alone, and not doing it to manage pain.', ['A lyric or a show.', 'Curiosity.', 'Use. If they’re panicking, stay calm, reduce stimulation, and get medical help if safety is in doubt.'], '“He said the tab was barely anything and then freaked out for hours.”', 'The “barely anything” story is how people get surprised. You can say that plainly without a chemistry lesson.', '“What do your friends think a tab will do, and for how long?”', 'Substances & Party Culture', 'attention'),
  t('robotripping', 'robotripping', ['robo', 'dxm', 'triple c'], 'Getting high on cough medicine that contains dextromethorphan, sometimes in dangerous combination products.', '“Triple C” refers to a cold medicine that has extra ingredients which make misuse worse, including risk of overdose. Don’t name doses or recipes. Misuse can cause panic, vomiting, seizures, and death. The brand in the bathroom is not “safe because it’s medicine.”', ['A meme or a dare.', 'Empty bottles or missing medicine.', 'A friend who is altered after taking cough medicine. Get medical help.'], '“Someone said robotripping is fine because it’s from a store.”', 'Store-bought is not a safety rating. Lock or track medicines if you have a concrete reason, and tell them why missing pills scare you, without a search-and-destroy speech as the opener.', '“Medicine from the cabinet can still put you in the hospital. Have you seen people try it?”', 'Substances & Party Culture', 'attention'),
  t('delta-8', 'delta-8', ['delta 8', 'diet weed', 'gas station gummies'], 'A hemp-derived cannabinoid sold in gummies and vapes, often where cannabis is illegal, with weaker oversight than people assume.', 'Teens call it diet weed or legal weed. Legal on a gas-station shelf is not the same as safe, dosed, or free of other chemicals. Edibles hit late, which leads to taking more.', ['A gas-station or online product they think doesn’t count.', 'A friend’s gummies.', 'A bad reaction. Treat heavy sedation or vomiting as medical.'], '“It’s just delta-8, so it’s not real weed.”', 'Correct the “doesn’t count” part. You still don’t need to turn a conversation into a lab manual.', '“What made you think the gas-station version was the safe one?”', 'Substances & Party Culture', 'attention'),
  t('nodding', 'nodding', ['nodding out', 'on the nod', 'he was nodding'], 'Drifting in and out of consciousness, a classic sign of opioid effects.', 'Sleepy after a late night is not this. Nodding from pills looks like someone cannot stay awake, head dropping, slow breathing. That can be an overdose. Call emergency services. Naloxone if you have it and know how. Don’t let a party “sleep it off.”', ['A misleading word for ordinary sleepiness. Context matters.', 'A warning sign after pills.', 'An emergency in progress.'], '“He was nodding in the chair and they said he was just tired.”', 'Teach the difference between tired and not-rouseable. Slow breathing and blue lips are an emergency, not a secret to keep for a friend.', '“If you can’t wake someone, you call for help. Do your friends know that?”', 'Substances & Party Culture', 'attention'),
  t('overdose', 'overdose', ['od', 'oded', 'overdosed'], 'Taking more of a drug than the body can handle. A medical emergency, not a punchline.', 'Teens use OD as exaggeration (“I OD’d on homework”). They also use it literally. The literal meaning needs a response plan: call emergency services, stay, use naloxone for suspected opioids, don’t worry about getting in trouble first.', ['Homework hyperbole.', 'A real event they’re scared about.', 'A friend in danger right now. Act.'], '“I od’d on caffeine. Also, someone at the party actually od’d last month and nobody called.”', 'Separate the joke from the story. The story where nobody called is the one to repair with a clear rule.', '“If that happened in front of you, what would you do before you did anything else?”', 'Substances & Party Culture', 'attention'),
  t('laced', 'laced', ['it was laced', 'laced pill', 'laced weed'], 'Mixed with a drug the person didn’t expect, often something stronger.', 'A common fear and sometimes a fact, especially with pills and powders. Cannabis “laced with fentanyl” stories are widely repeated and less commonly confirmed than pill stories, but unexpected contents are still a reason not to take mystery substances. Don’t teach testing as a green light.', ['A rumor after someone got very sick.', 'A reason they’re scared.', 'An excuse that may hide how much was taken. Believe the fear and get facts from a clinician if someone is sick.'], '“She thinks the gummy was laced because she panicked.”', 'Panic can also be the cannabis. You can say both: unexpected drugs are a real risk with pills, and a frightening high is still a reason to get help and to tell you.', '“What did they think they were taking, and what happened next?”', 'Substances & Party Culture', 'attention'),
  t('afters', 'afters', ['after party', 'the afters', 'going to afters'], 'The gathering after the main party or show.', 'Often looser supervision, later hours, and more substances than the event parents knew about. Not always. Sometimes it’s fries.', ['Food after a show.', 'A smaller party that moves houses.', 'The part of the night where the plan changes.'], '“The concert ends at 10 and then there’s afters.”', 'Ask where, whose adults, how they get home, and what changes after the official event. The second location is the one to pin down.', '“Where do afters happen, and who is the adult there?”', 'Substances & Party Culture', 'discuss'),
  t('turnt', 'turnt', ['turnt up', 'getting turnt', 'it’s about to be turnt'], 'Hyped, wild, or intoxicated. A party turned all the way up.', 'Energy word. Alcohol and cannabis may be implied and may not. The playlist might just be loud.', ['A fun, high-energy event.', 'Drinking or getting high.', 'A lyric.'], '“The gym was turnt and nobody had a drink. It was just the DJ.”', 'Ask what “up” included. Don’t assume a cup. Don’t ignore one either.', '“When a party is turnt, what’s actually going on?”', 'Substances & Party Culture', 'discuss'),
  t('eighth', 'eighth', ['an eighth', 'eighth of weed', 'eighth zip'], 'About 3.5 grams of cannabis, a standard small purchase amount.', 'If the sentence is about pizza, an eighth is a slice conversation. If it’s about a plug, a sack, or a price, it’s cannabis. Prices in texts are a clue.', ['Pizza. Look at the restaurant name.', 'A cannabis purchase.', 'A lyric.'], '“He wanted an eighth and a ride.”', 'A ride plus a quantity is a different ask than a ride to dinner. You can say no to being the logistics.', '“An eighth of what, and who was asking you for the ride?”', 'Substances & Party Culture', 'attention'),
  t('preroll', 'preroll', ['pre-roll', 'prerolls', 'infused preroll'], 'A cannabis joint rolled in advance, often bought that way.', 'Dispensary language that teens use even where they shouldn’t be buying. An infused preroll has extra concentrate and is stronger than they expect.', ['A product someone bought or found.', 'A plan to smoke.', 'A photo from a dispensary run by an older friend.'], '“They had prerolls in the center console.”', 'Access through older friends is a common path. Talk about that path. No need to discuss inhale technique.', '“Where did those come from, and who in the car is old enough to be the adult?”', 'Substances & Party Culture', 'attention'),
  t('boof', 'boof', ['boofed', 'that’s boof', 'boof cart'], 'Low quality, or a vulgar word for putting a drug in the rectum. Also a nonsense meme syllable.', 'You will mostly meet “this cart is boof” meaning the vape is fake or harsh. The sexual or route-of-use meaning exists and is crude. Don’t expand on methods. The quality meaning is the everyday one in teen drug talk.', ['“This product is bad.”', 'A meme sound.', 'A sexual or drug-route joke. You can name that it’s crude without a lesson in how.'], '“That cart is boof, don’t hit it.”', '“Don’t hit the mystery cart” is the right instinct even when the slang is gross. Fake cartridges are a real harm.', '“I’m less interested in the word and more interested in why carts are being passed around.”', 'Substances & Party Culture', 'discuss'),
  t('snus', 'snus', ['nicotine pouch cousin', 'zyn alternative', 'upper decky'], 'A tobacco pouch held in the lip. Teens also use the word loosely for nicotine pouches like Zyn.', 'Zyn is already in this library. Snus, Velo, and “upper deckys” are the same conversation: discreet nicotine, gum-line habits, and “it helps me focus.” It is still nicotine dependence.', ['A brand debate.', 'Use during school or sports.', 'A joke about dependence.'], '“Snus in the dugout so coaches can’t see vape clouds.”', 'The hiding is the tell. Talk about nicotine and sport, not just vape clouds.', '“If it’s for focus, what happens to focus when you don’t have it?”', 'Substances & Party Culture', 'attention'),
  t('shotgun a drink', 'shotgun-drink', ['shotgunning', 'shotgun a beer', 'shotgunned'], 'Punching a hole in a drink and chugging it fast, or forcing smoke from one person’s mouth to another’s.', 'Two party tricks share the word. Both are about speed and pressure. Alcohol shotgunning is binge drinking. Smoke shotgunning is intimacy plus substances. Don’t provide a how-to. The social pressure is the point to name.', ['A party stunt.', 'A video they’re copying.', 'Pressure. “Don’t be boring” is the script.'], '“They wanted me to shotgun and I said no.”', 'Back the no. Speed-drinking is how blackouts start. You can say that in one sentence.', '“What did people say when you refused?”', 'Substances & Party Culture', 'attention'),
  t('tipsy', 'tipsy', ['a little tipsy', 'catching a buzz', 'buzzed light'], 'Mildly drunk. Less impaired than “wasted,” which is already in this library.', 'Teens use it to make drinking sound cute and controlled. It still means alcohol. “Tipsy” can be the word they use on the way to a blackout, or it can be accurate.', ['A small amount of alcohol.', 'A minimization.', 'A lyric or a joke.'], '“I was only tipsy.”', 'Ask what only means: how much, whose alcohol, how they got home. The cute word isn’t the measurement.', '“What does tipsy look like for your friends—one drink, or they just say that?”', 'Substances & Party Culture', 'discuss'),
  t('vyvanse', 'vyvanse', ['lisdexamfetamine', 'vyvanse not addy', 'study meds'], 'A prescription stimulant for ADHD. Also shared or sold as a study drug.', 'Adderall is already covered under addy. Vyvanse is the sibling teens name when they think it’s “the safer ADHD one.” Sharing prescriptions is still misuse. Someone else’s pill is not a focus strategy.', ['Their own prescribed medicine. That’s medical privacy and practical support.', 'A classmate selling pills during exams.', 'Pressure to try one before a test.'], '“People want Vyvanse for finals week.”', 'If it’s their prescription, talk about keeping it in their control. If it’s someone else’s, the risk includes heart effects and a drug charge, which you can say without a chemistry lecture.', '“Is this your prescription, or pills moving around school?”', 'Substances & Party Culture', 'attention'),
  t('salt nic', 'salt-nic', ['nic salts', 'nicotine salts', '50mg salt'], 'A nicotine formulation in many vapes that feels smoother and can deliver a lot of nicotine.', '“Smooth” is why teens think a device is mild. High-strength salts can make them sick (nic-sick) and dependent quickly. You don’t need the milligram chart to say that smoother is not weaker.', ['Device talk.', 'A reason they think it’s not a big deal.', 'Nic-sick after a strong puff.'], '“It’s salt nic so it doesn’t even burn.”', 'Translate: less burn can mean easier to overuse. The dependence conversation is the same one as disposables.', '“What made you think smooth meant mild?”', 'Substances & Party Culture', 'attention'),
  t('juul', 'juul', ['juuling', 'juuled', 'the juul'], 'An older nicotine-vape brand that became the generic word for vaping for a while.', 'Still said, even when the device is a disposable of another brand. “Hit the Juul” may mean “hit the vape.” The behavior is nicotine either way.', ['A generic word for a vape.', 'An actual older device.', 'Nostalgia or a meme about a crackdown.'], '“Nobody even says Juul anymore, but teachers still do.”', 'Follow the behavior, not the brand cycle. The library’s vape, dispo, and Geek Bar entries are the current objects.', '“When adults say Juul and you say elf bar, are you talking about the same habit?”', 'Substances & Party Culture', 'attention'),
  t('airtag', 'airtag', ['air tag', 'airtags', 'tile tracker'], 'A small Bluetooth tracker. Useful for keys. Also used to track a person without their knowledge.', 'Phones now warn about unknown trackers traveling with you. Teens should know how to check. An ex, a bully, or a stranger can hide one in a bag or a car.', ['Finding lost keys or a bag they consented to share.', 'A joke.', 'A tracker they didn’t agree to. That’s stalking. Remove it and tell a trusted adult.'], '“My phone said an AirTag was moving with me.”', 'Don’t ignore the alert. Apple and similar companies have public steps to find and disable an unknown tracker. If a person is attached to the threat, involve a safe adult and, if needed, police. Don’t confront the stalker alone.', '“If your phone warns you about a tracker, tell me. We’ll follow the phone’s steps together.”', 'Sensitive Safety Topics', 'attention'),
  t('life360', 'life360', ['life 360', 'the circle', 'location sharing app'], 'A family location-sharing app. Also a thing teens complain about, disable, or spoof.', 'It can be a real safety agreement. It can also feel like surveillance that pushes secrecy. The useful question is whether the rule was made together and what happens when they’re honest about a dead battery.', ['A known family tool.', 'A teen looking for a way to appear somewhere they’re not.', 'A friend whose parents watch every step. Empathy before a speech.'], '“I’m not sneaking out. I just hate being a dot.”', 'If you use it, say what you do with the dot and what you won’t do: no surprise interrogations over a grocery stop. If they’re spoofing, the trust problem is already here.', '“What would make location sharing feel like a backup instead of a leash?”', 'Sensitive Safety Topics', 'discuss'),
  t('random video chat', 'random-video-chat', ['omegle', 'ometv', 'chatroulette'], 'Sites and apps that pair you on camera with strangers. Omegle is gone. The category is not.', 'People still seek the same thrill on replacement sites. Strangers include adults, sexual content appears quickly, and “skip” does not make it safe. Recording a stranger, or being recorded, is part of the risk.', ['Curiosity or a dare.', 'A friend showing them a shocking clip from one.', 'An adult on the other side asking a minor to stay. Leave and tell someone.'], '“We went on a random chat for five seconds and it was already weird.”', 'Believe the weird. The skill is closing the tab and not screenshotting anyone. If someone asked them for sexual content or their location, report with an adult.', '“You can tell me what popped up. You’re not in trouble for closing it and telling me.”', 'Sensitive Safety Topics', 'attention'),
  t('nudify', 'nudify', ['nudify app', 'undress ai', 'ai nude generator'], 'Tools that take a normal photo and generate a fake nude of that person.', 'This is image-based abuse. A classmate’s school photo is enough source material. Being fake does not make it harmless or legal. Don’t name sites or steps. If an image exists, don’t forward it, don’t ask to see it, and get help from the school and, where appropriate, the police or a cyber tip line.', ['A rumor that a tool exists.', 'A threat to make one.', 'An image already circulating. Support the target. They did nothing wrong.'], '“Someone said they could nudify the yearbook photo.”', 'Treat the threat as real. The person in the photo is the victim even if they never took a nude. Your child should not open, save, or send it.', '“If an image like that exists, we don’t open it and we don’t pass it on. We get help. Has one already been sent?”', 'Sensitive Safety Topics', 'attention'),
  t('phishing', 'phishing', ['phish', 'fake login', 'credential scam'], 'A fake message or page that tricks someone into giving a password, code, or card number.', 'It looks like Discord, a game, a bank, or a teacher. The tell is urgency plus a link plus a login. You never need someone’s password to give them a gift.', ['A text from “the school” or “Discord support.”', 'A friend whose account is already stolen and is now messaging others.', 'A code prompt. Codes are as sensitive as passwords.'], '“Discord said I have to verify or lose the account.”', 'Real companies don’t need the password typed into a random link. When a friend’s account asks for money or codes, it’s often no longer your friend typing.', '“When a login page shows up from a link, what’s the move before you type?”', 'Sensitive Safety Topics', 'attention'),
  t('ip grabber', 'ip-grabber', ['ip logger', 'grabify', 'i have your ip'], 'A link that records a rough network address when someone clicks it, then used as a threat.', 'Teens threaten “I have your IP” as if that were a home address and a weapon. Often they have a city-level clue or nothing useful, and the point is fear. Don’t explain how to run a grabber. Do explain that clicking random links is a bad idea and that the threat is often bluster plus harassment.', ['A scare line in an argument.', 'A link sent as a “quiz” or a meme.', 'Harassment. Save it and block. A real threat of violence still gets reported.'], '“He sent a link and then said he had my IP and was coming.”', 'Don’t click more links to “check.” Screenshot the threat, block, and if there’s a credible threat of harm, involve school or police. You can tell your child the brag is often bigger than the data without promising they’re invisible.', '“Don’t click it. Show me the threat itself. We’ll block and decide who else needs to see it.”', 'Sensitive Safety Topics', 'attention'),
  t('parcel mule', 'parcel-mule', ['reshipping job', 'package reship', 'you keep a cut'], 'A “job” that asks a teen to receive packages and forward them, keeping a cut. It is often stolen-goods laundering.', 'The pitch is easy money, work from home, and a too-good paycheck. Packages bought with stolen cards show up in the teen’s name. They become the visible criminal.', ['A DM job offer.', 'A friend who already received a box.', 'A check that arrives before any real work. That’s a classic setup.'], '“They’ll pay me $300 a week to forward packages. I don’t even have to buy anything.”', 'The rule is simple: don’t receive mystery packages, don’t forward them, don’t deposit surprise checks. If a box already arrived, don’t ship it on. Talk to the police or a trusted adult before you “just send it back” into the scam.', '“Legit jobs don’t need a teenager’s address as the warehouse. Have any boxes actually shown up?”', 'Sensitive Safety Topics', 'attention'),
  t('brigading', 'brigading', ['brigade', 'raid the comments', 'mass report'], 'Organizing a crowd to flood someone’s comments, reports, or server to punish them.', 'Different from a few people disagreeing. Brigading is coordinated. It can get a person banned, doxed, or swarmed. Mass-reporting can be abuse of the tools.', ['A fandom war they’re watching.', 'A server “raid” that is actually harassment.', 'Pressure to join in.'], '“If we all report at 8, the account dies.”', 'They can refuse. Participating in a report raid or a dox is harm, even from the couch. One real report of a real violation is different from a swarm.', '“What happens to the person on the other end of a raid like that?”', 'Sensitive Safety Topics', 'attention'),
  t('cyberbullying', 'cyberbullying', ['online bullying', 'group chat bullying', 'pile on chat'], 'Bullying that happens in chats, comments, posts, or stories. It follows the target home.', 'The library covers a lot of the tactics: snark pages, confession pages, dogpiles, leaks. This is the umbrella. It counts even if the bully smiles and says it was a joke.', ['A one-off insult.', 'A campaign: exclusion, edits, fake accounts, screenshots.', 'Your child as target, witness, or participant. All three need a conversation.'], '“It’s not bullying if it’s in the meme chat.”', 'The meme chat is still a room with a person in it. Ask who can’t defend themselves and who is enjoying the pile.', '“If we put the joke on a poster at school, would it still feel like a joke?”', 'Sensitive Safety Topics', 'discuss'),
  t('jailbait', 'jailbait', ['jail bait', 'she’s jailbait'], 'A predatory word that sexualizes a minor and treats their age as the temptation.', 'There is no harmless teen use that you need to chuckle at. If an adult uses it about a child, that is a warning about the adult. If teens use it about each other, they are repeating a script that turns kids into targets. Don’t repeat the word for effect. Don’t ask for the images or the details of bodies.', ['A lyric or a video they heard.', 'Teens rating classmates. Shut the rating down.', 'An adult describing a minor this way. Treat it as a safety issue.'], '“He called a freshman that and the seniors laughed.”', 'The laugh is the contagion. Tell your child the word is about sexualizing kids, it isn’t a compliment, and adults who use it are unsafe. If an adult is contacting a minor, report.', '“That word isn’t a joke here. Who said it, and was an adult involved?”', 'Sensitive Safety Topics', 'attention'),
  t('age regression', 'age-regression', ['agere', 'little space', 'cg/l'], 'Acting or feeling younger as a coping comfort. In some internet spaces the same words are used for sexual roleplay. Those are not the same thing.', 'Nonsexual age regression is a coping style some teens use when stressed: cartoons, stuffies, a younger voice. Sexual “little” roleplay is an adult fetish and is not appropriate involving minors. You can protect the coping and reject the sexual version. Don’t mix them up on purpose, and don’t shame a stuffed animal.', ['A stress coping tool.', 'A fandom aesthetic of cute kid-like things.', 'Sexual roleplay, especially with an adult. That is a safety issue.'], '“I just want my show and a blanket. It’s not weird, I’m overwhelmed.”', 'Ask who else is in the space and whether anyone is sexualizing it. An adult inviting a minor into sexual roleplay is exploitation, even if the minor thinks it’s comfort.', '“Is this something you do to calm down, and is any adult treating it as sexual?”', 'Sensitive Safety Topics', 'attention'),
  t('dead dove', 'dead-dove', ['dead dove do not eat', 'dddne'], 'A fanfiction warning: the dark tags are serious, not a joke and not a bait-and-switch.', 'The name comes from a TV joke about a bag labeled “dead dove” that does, in fact, contain a dead dove. On stories it means: if the tags say graphic violence or sexual violence, they’re real. It is a warning label, not a recommendation.', ['A reader who understands warnings.', 'A teen clicking through anyway.', 'Content involving minors and sex. That tag is a stop, not a curiosity.'], '“It said dead dove and I opened it anyway. I feel sick.”', 'Believe the sick feeling. Warnings are allowed to be heeded late. If the material sexualized minors, say clearly that seeking or keeping it is serious, and get help without a humiliation scene.', '“You can close it. What did you need in order to stop, and do you want help finding stories that don’t wreck you?”', 'Sensitive Safety Topics', 'attention'),
  t('proship', 'proship', ['pro ship', 'anti-ship', 'ship discourse'], 'A fandom stance: “proship” generally opposes harassment of people over what fictional pairings they write. The fights are vicious.', 'The discourse often includes sexual fiction, including age-gap or “underage” fictional pairings. You do not have to adjudicate ship wars. You do have to be clear that real minors are not a pairing, and that harassment campaigns are not activism.', ['A messy fandom argument they’re watching.', 'Fiction that is dark but clearly fictional.', 'Sexual content about minors, drawn or written. That’s the line to name.'], '“The timeline is proship versus anti again and it’s nasty.”', 'Help them leave a war. Be explicit that drawings and stories sexualizing children are not a team sport. Harassment of real people over taste is also not required.', '“You can exit a discourse. Is any of it about real kids, or about people getting threatened?”', 'Sensitive Safety Topics', 'discuss'),
  t('dubcon', 'dubcon', ['noncon', 'dubious consent', 'non-con fic'], 'Labels on sexual stories: dubious consent, or no consent. They mean coercion or assault is part of the fiction.', 'Teens meet these tags in fanfic. The tags are warnings. Fiction is not a how-to, and it is also not a place to skip if the reader is a minor who didn’t understand the tag. Don’t describe scenes. Do use the moment to talk about real consent: silence, pressure, and “they didn’t say no” are not yes.', ['A tag they didn’t understand.', 'A story that upset them.', 'A belief that reluctance is the same as romance. Talk about that belief.'], '“The tag said dubcon and I had to look it up.”', 'Define it plainly: one person did not freely agree. Ask how that differs from flirtation in real life. If they’re distressed, stay with the feeling.', '“In real life, what does a clear yes sound like, and what doesn’t count?”', 'Sensitive Safety Topics', 'attention'),
  t('y/n', 'y-n', ['yn', 'x reader', 'reader insert'], '“Your name.” A story written so the reader is the love interest, with Y/N where the name goes.', 'Extremely common fanfiction. Often romantic, sometimes sexual. “X reader” means the same format. It can be sweet escapism or explicit content aimed at a young reader.', ['A harmless daydream story.', 'Romantic fiction with a self-insert.', 'Explicit sexual fiction. Check tags and ratings.'], '“It’s a Y/N and the character takes you to the dance.”', 'Ask the rating the way you would for a show. Self-insert romance can be intense. That’s a reason for tags, not a reason to snoop through every chapter.', '“Do those stories stay at the dance, or do they get sexual?”', 'Relationships & Dating', 'discuss'),
  t('smut', 'smut', ['lemon', 'spicy fic', 'explicit fic'], 'Fan or original fiction that is sexually explicit. “Lemon” is an older word for the same thing.', 'Teens recommend smut the way they recommend playlists. Some of it is between fictional adults. Some is not appropriate for the reader’s age, and some sexualizes minors. You can be direct without a scene-by-scene talk.', ['Fiction about adults that an older teen is reading.', 'A younger child who does not realize what they opened.', 'Content involving minors. Stop, don’t save, don’t share.'], '“The group chat is swapping smut recommendations.”', 'Ask ages in the story and the age of the reader. You can set a boundary: explicit fiction isn’t a group-chat activity, and anything with kids in it is a no.', '“Are the characters adults, and are you comfortable telling me if something feels too far?”', 'Relationships & Dating', 'attention'),
  t('thinspo', 'thinspo', ['thinspiration', 'thin spo', 'bonespo'], 'Images and posts meant to inspire extreme thinness. Bonespo pushes an even more skeletal ideal.', 'This is eating-disorder fuel, not fitness. It lives in tags, private accounts, and group chats. Don’t go hunting for the worst images with your child watching. Do take a saved folder seriously, without weight talk, body critiques, or a new diet.', ['A word they saw and found disturbing.', 'A saved folder or a tag they follow.', 'A friend who is deep in it. Compassion, not gossip.'], '“The tag was thinspo and I know I shouldn’t have opened it.”', 'Thank the honesty. Get professional help if restriction is happening. Remove the feed trigger. Don’t replace it with “healthy” weight-loss content.', '“Opening it doesn’t make you bad. Are you trying to make your body match those pictures?”', 'Sensitive Safety Topics', 'attention'),
  t('meanspo', 'meanspo', ['mean spo', 'hate speech to stay thin'], 'Insults aimed at pushing someone to eat less. Harassment dressed up as “motivation.”', 'People send or request cruelty about their bodies so they will restrict. It is self-harm-adjacent and it is also bullying when aimed at others. Don’t quote the insults back.', ['They stumbled on it.', 'They asked someone to be cruel to them.', 'A friend is in that dynamic.'], '“Someone offered meanspo like it was a favor.”', 'Say clearly that you will not insult their body and you don’t want strangers doing it either. If they’re requesting abuse, they need care, not a harsher mirror.', '“You never have to earn food by letting people be cruel to you. Can we get you support that isn’t a stranger’s insults?”', 'Sensitive Safety Topics', 'attention'),
  t('body check', 'body-check', ['body checking', 'body check video', 'collarbone check'], 'Posting or repeatedly looking at your body to judge how thin or muscular it is.', 'A mirror, a measurement, a “what I eat in a day” that is really a body display. Fitness content can hide it. The loop tightens anxiety. It is a known eating-disorder behavior and also a trend.', ['A single outfit video. Maybe just fashion.', 'Repeated measuring, mirror checks, or asking “am I bigger?”', 'A feed of other people’s checks. It spreads.'], '“It’s just a body check, everyone does them.”', 'Everyone doesn’t. If they’re checking to feel allowed to eat or to exist, bring in a professional. Keep comments off their body at home, including “you look healthy.”', '“When you check, what are you hoping to feel, and what do you feel instead?”', 'Sensitive Safety Topics', 'attention'),
  t('goal weight', 'goal-weight', ['gw', 'ugw', 'cw hw'], 'A target weight in eating-disorder communities. UGW means an “ultimate” goal, often dangerously low. CW and SW mean current and start weights.', 'These abbreviations are a code of restriction culture. A gym goal discussed with a doctor is a different sentence and usually doesn’t look like a stack of secret acronyms. Don’t set a lower number together. Don’t turn dinner into a negotiation.', ['A sports weight class with a coach. Still worth sanity-checking.', 'Secret numbers and a shrinking target.', 'A community encouraging them to go lower.'], '“My GW isn’t even that low.”', '“Not that low” inside these communities is not reassuring. Get pediatric or eating-disorder-informed care. At home, feed them and drop the numbers talk.', '“I’m not going to help chase a number. I am going to help you get care and eat. Can we start there?”', 'Sensitive Safety Topics', 'attention'),
  t('middleman scam', 'middleman-scam', ['middleman', 'trusted mm', 'fake middleman'], 'A “trusted” third person in an online trade who is actually working with the thief.', 'Common in game-item and account trades. Both sides think the middleman is protection. Sometimes the middleman is the scam. The safe version is not trading away valuables with strangers at all.', ['A friend offering to middleman a trade.', 'A stranger with a fancy profile and fake vouchers.', 'A loss they’re ashamed of. Shame is how the next kid gets hit too.'], '“The middleman seemed legit because he had a server.”', 'Servers and voucher screenshots are costumes. Help them lock the account. Don’t try to “trade back” with the same people.', '“Let’s secure the account. Chasing them in DMs is how the second loss happens.”', 'Sensitive Safety Topics', 'attention'),
  t('free vbucks scam', 'free-vbucks-scam', ['vbucks generator', 'free robux generator', 'generator site'], 'A site or video that promises free game currency if you log in, complete offers, or download something.', 'The currency never arrives. The login does. Survey offers can bill a phone. Downloads can steal the account. This sits beside the Robux and V-Bucks entries as the scam shape itself.', ['A link a friend forwarded.', 'A YouTube tutorial.', 'An account that is already acting weird after a login.'], '“The generator asked for my password and my mom’s email.”', 'Change passwords from a real site you type yourself, turn on two-factor, and tell the platform. Don’t pay anyone who says they can get the items back.', '“We’ll fix the account from the official app. No more generators, even if a friend swears.”', 'Sensitive Safety Topics', 'attention'),
  t('cashapp flip', 'cashapp-flip', ['venmo flip', 'paypal flip', 'screenshot the balance'], 'A stranger asks for a small payment and promises to send back more. Often they want a screenshot of the balance first.', 'The screenshot helps them impersonate the account. The “flip” never returns. It is the same idea as the money-flip entry already in this library, now on the apps teens actually use.', ['A DM from a hacked friend’s account.', 'A “business” offer.', 'A request for a balance screenshot. That is the tell.'], '“He only needs $20 and a screenshot to flip it to $200.”', 'Screenshots of balances and codes are account keys. Don’t send them. If money left, contact the app quickly and file a report. Speed matters more than a speech.', '“We can call the app’s support together. Sending a second payment won’t unlock the first.”', 'Sensitive Safety Topics', 'attention'),
  t('Replika / Chai', 'replika-chai', ['replika', 'chai app', 'talkie app'], 'Named chatbot apps built to feel like a friend, partner, or therapist.', 'Product names teens use for AI companions. The risk is secrecy, sexual roleplay, and taking crisis advice from a bot that is not a person and not a clinician.', ['Casual entertainment.', 'A place they tell things they won’t tell a person.', 'Romantic or sexual roleplay, sometimes with a bot that also engages minors. That’s a problem to interrupt.'], '“Don’t laugh. I talk to the bot more than people.”', 'Don’t laugh. Ask what the bot gives them. If they’re in crisis, a bot is not the plan. If the bot is sexual, say that companions designed for adults aren’t for them, and look at settings together.', '“What do you tell the bot that feels hard to tell me? I want to be usable, not just alarmed.”', 'Social Media Culture', 'attention'),
  t('ragebaiting', 'rage-baiting', ['rage baiting', 'engagement bait comment', 'ratio bait'], 'Posting something infuriating so people will argue and boost it.', 'Rage bait is already in this library as a noun. The verb form is what they accuse each other of in comments: “you’re ragebaiting.” Sometimes the accusation is itself a way to avoid a real point.', ['They spotted a tactic.', 'They tried it as a joke.', 'A comment section making them miserable.'], '“Don’t reply, it’s ragebait.”', 'Not replying is a skill. You can praise the media literacy and still ask whether they spend an hour “not replying.”', '“How often do you win by scrolling past?”', 'Social Media Culture', 'harmless'),
  t('side character', 'side-character', ['side character energy', 'background character', 'side-character energy'], 'Someone treated as forgettable, passive, or not worth the plot.', 'The put-down cousin of main-character talk. It can be a joke about laying low, or a way to shame a quieter kid.', ['A joke about skipping the spotlight.', 'A put-down: stop being a side character.', 'Story framing of an ordinary day.'], '“Stop being a side character and come to the table.”', 'An invitation can be kind. Contempt for quiet people is not. Not everyone wants the protagonist job.', '“Who gets called a side character, and do they think it’s funny?”', 'Social Media Culture', 'discuss'),
  t('ick list', 'ick-list', ['icks list', 'gave me the ick', 'ick tok'], 'A crowdsourced list of tiny behaviors that kill attraction.', 'The ick is already in this library. The list format turns personal taste into a public standard and can get cruel fast, especially about bodies, disability, or awkwardness.', ['A funny personal preference.', 'A video mocking a specific classmate.', 'A script that makes ordinary humans undateable.'], '“The ick list includes eating apples whole. We’re all doomed.”', 'Taste is allowed. Public humiliation and body rules are the part to edit out.', '“Which icks are yours, and which ones are just mean?”', 'Relationships & Dating', 'discuss'),
]
